function(container, apiUrl, tables) {
  // ログイン試行回数を管理
  let loginAttempts = parseInt(localStorage.getItem('loginAttempts') || '0');
  let lastAttemptTime = parseInt(localStorage.getItem('lastAttemptTime') || '0');

  // アカウントロック時間（5分）
  const LOCK_DURATION = 5 * 60 * 1000;
  const MAX_ATTEMPTS = 5;

  // DOM要素の取得
  const userIdInput = container.querySelector('#user-id');
  const passwordInput = container.querySelector('#password');
  const togglePasswordBtn = container.querySelector('#toggle-password');
  const rememberMeCheckbox = container.querySelector('#remember-me');
  const loginForm = container.querySelector('#login-form');
  const errorMessage = container.querySelector('#error-message');
  const forgotPasswordLink = container.querySelector('#forgot-password');

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove('hidden');
  }

  // エラーメッセージ非表示関数
  function hideError() {
    errorMessage.classList.add('hidden');
  }

  // パスワード表示/非表示切り替え
  togglePasswordBtn.addEventListener('click', () => {
    const isPassword = passwordInput.type === 'password';
    passwordInput.type = isPassword ? 'text' : 'password';
    togglePasswordBtn.textContent = isPassword ? '🙈' : '👁';
  });

  // バリデーション関数
  function validateInputs() {
    const userId = userIdInput.value.trim();
    const password = passwordInput.value.trim();

    if (!userId && !password) {
      showError('ユーザーIDとパスワードを入力してください');
      return false;
    }

    if (!userId) {
      showError('ユーザーIDを入力してください');
      return false;
    }

    if (!password) {
      showError('パスワードを入力してください');
      return false;
    }

    // 特殊文字チェック（XSS/SQLインジェクション対策）
    const dangerousChars = /<script|javascript:|DROP\s+TABLE|SELECT\s+\*|INSERT\s+INTO|DELETE\s+FROM/i;
    if (dangerousChars.test(userId) || dangerousChars.test(password)) {
      showError('不正な文字が含まれています');
      return false;
    }

    return true;
  }

  // アカウントロック状態チェック
  function isAccountLocked() {
    if (loginAttempts >= MAX_ATTEMPTS) {
      const timeSinceLastAttempt = Date.now() - lastAttemptTime;
      if (timeSinceLastAttempt < LOCK_DURATION) {
        return true;
      } else {
        // ロック時間が過ぎたらリセット
        loginAttempts = 0;
        localStorage.setItem('loginAttempts', '0');
        return false;
      }
    }
    return false;
  }

  // ログイン試行回数の記録
  function recordFailedAttempt() {
    loginAttempts++;
    lastAttemptTime = Date.now();
    localStorage.setItem('loginAttempts', loginAttempts.toString());
    localStorage.setItem('lastAttemptTime', lastAttemptTime.toString());
  }

  // ログイン試行回数のリセット
  function resetLoginAttempts() {
    loginAttempts = 0;
    localStorage.removeItem('loginAttempts');
    localStorage.removeItem('lastAttemptTime');
  }

  // ログイン処理
  async function handleLogin(userId, password, rememberMe) {
    try {
      // アカウントロック状態チェック
      if (isAccountLocked()) {
        showError('アカウントがロックされました。しばらく時間をおいてから再度お試しください。');
        return false;
      }

      // ユーザーテーブルからユーザー情報を取得
      const users = await window.aivicApi.list(0); // ユーザーテーブル
      if (!users) {
        showError('システムエラーが発生しました。しばらく時間をおいてから再度お試しください。');
        return false;
      }

      // ユーザー認証
      const user = users.find(u => 
        u.ユーザー名 === userId && 
        u.有効フラグ === true
      );

      if (!user) {
        recordFailedAttempt();
        showError('ユーザーIDまたはパスワードが正しくありません');
        return false;
      }

      // パスワード検証（実際の実装では暗号化されたパスワードと比較）
      // ここでは簡易的にプレーンテキストで比較
      if (user.パスワードハッシュ !== password) {
        recordFailedAttempt();
        showError('ユーザーIDまたはパスワードが正しくありません');
        return false;
      }

      // ログイン成功
      resetLoginAttempts();

      // 最終ログイン日時を更新
      await window.aivicApi.update(0, user.ユーザーID, {
        最終ログイン日時: new Date().toISOString()
      });

      // セッション情報を保存
      const sessionData = {
        userId: user.ユーザーID,
        userName: user.ユーザー名,
        displayName: user.氏名,
        department: user.所属部署,
        role: user.権限レベル,
        loginTime: new Date().toISOString()
      };

      if (rememberMe) {
        localStorage.setItem('userSession', JSON.stringify(sessionData));
      } else {
        sessionStorage.setItem('userSession', JSON.stringify(sessionData));
      }

      // メイン画面（工数記録画面）に遷移
      window.showScreen("scr-1778907133295");
      return true;

    } catch (error) {
      console.error('Login error:', error);
      showError('システムエラーが発生しました。しばらく時間をおいてから再度お試しください。');
      return false;
    }
  }

  // フォーム送信イベント
  loginForm.addEventListener('submit', async (e) => {
    e.preventDefault();
    hideError();

    if (!validateInputs()) {
      return;
    }

    const userId = userIdInput.value.trim();
    const password = passwordInput.value.trim();
    const rememberMe = rememberMeCheckbox.checked;

    // ログインボタンを無効化
    const loginButton = container.querySelector('#login-button');
    loginButton.disabled = true;
    loginButton.textContent = 'ログイン中...';

    try {
      await handleLogin(userId, password, rememberMe);
    } finally {
      // ログインボタンを有効化
      loginButton.disabled = false;
      loginButton.textContent = 'ログイン';
    }
  });

  // パスワードを忘れた場合のリンク
  forgotPasswordLink.addEventListener('click', (e) => {
    e.preventDefault();
    // パスワードリセット画面に遷移（実際の実装では適切な画面IDを指定）
    alert('パスワードリセット機能は準備中です。管理者にお問い合わせください。');
  });

  // 既存のセッションをチェック
  const existingSession = localStorage.getItem('userSession') || sessionStorage.getItem('userSession');
  if (existingSession) {
    try {
      const sessionData = JSON.parse(existingSession);
      // セッションが有効な場合は自動的にメイン画面に遷移
      window.showScreen("scr-1778907133295");
    } catch (error) {
      // セッションデータが無効な場合は削除
      localStorage.removeItem('userSession');
      sessionStorage.removeItem('userSession');
    }
  }

  // 入力フィールドにフォーカスを当てる
  userIdInput.focus();
}

function(container, apiUrl, tables) {
  let currentWorkRecord = null;
  let startTime = null;
  let pauseStartTime = null;
  let totalPauseTime = 0;
  let timerInterval = null;
  let workStatus = 'waiting'; // waiting, working, paused, completed

  // 現在時刻更新
  function updateCurrentTime() {
    const now = new Date();
    const timeStr = now.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
    container.querySelector('#current-time').textContent = timeStr;
  }

  // 経過時間更新
  function updateElapsedTime() {
    if (!startTime) return;

    const now = new Date();
    let elapsed = now - startTime - totalPauseTime;

    if (workStatus === 'paused' && pauseStartTime) {
      elapsed -= (now - pauseStartTime);
    }

    const hours = Math.floor(elapsed / (1000 * 60 * 60));
    const minutes = Math.floor((elapsed % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((elapsed % (1000 * 60)) / 1000);

    const timeStr = `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
    container.querySelector('#elapsed-time').textContent = timeStr;
  }

  // 作業状態更新
  function updateWorkStatus(status) {
    workStatus = status;
    const statusElement = container.querySelector('#work-status');
    const startBtn = container.querySelector('#start-work-btn');
    const pauseBtn = container.querySelector('#pause-work-btn');
    const endBtn = container.querySelector('#end-work-btn');

    switch (status) {
      case 'waiting':
        statusElement.textContent = '待機中';
        startBtn.disabled = false;
        pauseBtn.disabled = true;
        endBtn.disabled = true;
        break;
      case 'working':
        statusElement.textContent = '作業中';
        startBtn.disabled = true;
        pauseBtn.disabled = false;
        endBtn.disabled = false;
        break;
      case 'paused':
        statusElement.textContent = '中断中';
        startBtn.disabled = true;
        pauseBtn.disabled = true;
        endBtn.disabled = false;
        break;
      case 'completed':
        statusElement.textContent = '完了';
        startBtn.disabled = false;
        pauseBtn.disabled = true;
        endBtn.disabled = true;
        break;
    }
  }

  // 作業項目マスタ読み込み
  async function loadWorkItems() {
    const workItems = await window.aivicApi.list(3); // 作業項目マスタ
    const select = container.querySelector('#work-item-select');
    select.innerHTML = '<option value="">選択してください</option>';

    if (workItems) {
      workItems
        .filter(item => item.有効フラグ)
        .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
        .forEach(item => {
          const option = document.createElement('option');
          option.value = item.作業項目ID;
          option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
          select.appendChild(option);
        });
    }
  }

  // 本日の作業履歴表示
  function renderTodayHistory(records) {
    const tbody = container.querySelector('#today-history-tbody');
    const today = new Date().toDateString();

    const todayRecords = records.filter(record => {
      const recordDate = new Date(record.作業日).toDateString();
      return recordDate === today;
    }).sort((a, b) => new Date(a.作業開始時刻) - new Date(b.作業開始時刻));

    tbody.innerHTML = todayRecords.map(record => {
      const startTime = new Date(record.作業開始時刻).toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
      const endTime = record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' }) : '-';
      const workHours = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}:${(record.作業時間 % 60).toString().padStart(2, '0')}` : '-';

      return `
        <tr data-id="${record.作業記録ID}">
          <td>${startTime}</td>
          <td>${endTime}</td>
          <td>${record.作業種別 || ''}</td>
          <td>${record.作業場所 || ''}</td>
          <td>${workHours}</td>
          <td>${record.進捗状況 || ''}</td>
          <td>
            <button class="action-btn secondary edit-btn" data-id="${record.作業記録ID}" style="font-size: 11px; padding: 4px 8px;">編集</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 作業開始
  async function startWork() {
    const workItemId = container.querySelector('#work-item-select').value;
    const workLocation = container.querySelector('#work-location').value.trim();
    const workContent = container.querySelector('#work-content').value.trim();

    if (!workItemId) {
      alert('作業項目を選択してください');
      return;
    }

    if (!workLocation) {
      alert('作業場所を入力してください');
      return;
    }

    if (!workContent) {
      alert('作業内容を入力してください');
      return;
    }

    const now = new Date();
    startTime = now;
    totalPauseTime = 0;

    // 作業記録を作成
    const workRecord = {
      作業員ID: 'current-user-id', // 実際の実装では認証済みユーザーIDを使用
      作業日: now.toISOString(),
      作業開始時刻: now.toISOString(),
      作業終了時刻: null,
      作業時間: null,
      プロジェクト名: 'プロジェクト名', // 実際の実装では選択されたプロジェクト
      作業場所: workLocation,
      作業種別: container.querySelector('#work-item-select option:checked').textContent,
      作業内容: workContent,
      進捗状況: '作業中',
      備考: container.querySelector('#work-memo').value.trim(),
      承認状態: '未承認',
      承認者ID: null,
      承認日時: null,
      作成日時: now.toISOString(),
      更新日時: now.toISOString(),
      作成者ID: 'current-user-id'
    };

    currentWorkRecord = await window.aivicApi.save(1, workRecord); // 作業記録テーブル
    if (currentWorkRecord) {
      updateWorkStatus('working');

      // タイマー開始
      timerInterval = setInterval(updateElapsedTime, 1000);

      // 履歴更新
      const records = await window.aivicApi.list(1);
      if (records) renderTodayHistory(records);
    }
  }

  // 作業中断
  function pauseWork() {
    if (workStatus !== 'working') {
      alert('作業が開始されていません');
      return;
    }

    container.querySelector('#pause-modal').style.display = 'block';
  }

  // 中断実行
  async function executePause() {
    const reasonCategory = container.querySelector('#pause-reason-category').value;
    const reasonDetail = container.querySelector('#pause-reason-detail').value.trim();

    if (!reasonCategory) {
      alert('中断理由区分を選択してください');
      return;
    }

    if (!reasonDetail) {
      alert('中断理由を入力してください');
      return;
    }

    const now = new Date();
    pauseStartTime = now;

    // 中断記録を作成
    const pauseRecord = {
      作業記録ID: currentWorkRecord.作業記録ID,
      中断開始日時: now.toISOString(),
      中断終了日時: null,
      中断理由区分: reasonCategory,
      中断理由詳細: reasonDetail,
      中断時間: null,
      影響度: '中程度',
      対応状況: '対応中',
      記録者ID: 'current-user-id',
      作成日時: now.toISOString(),
      更新日時: now.toISOString()
    };

    const saved = await window.aivicApi.save(2, pauseRecord); // 中断記録テーブル
    if (saved) {
      updateWorkStatus('paused');
      container.querySelector('#pause-modal').style.display = 'none';

      // フォームクリア
      container.querySelector('#pause-reason-category').value = '';
      container.querySelector('#pause-reason-detail').value = '';
    }
  }

  // 作業終了
  async function endWork() {
    if (workStatus !== 'working' && workStatus !== 'paused') {
      alert('作業が開始されていません');
      return;
    }

    const now = new Date();

    // 中断中の場合は中断時間を加算
    if (workStatus === 'paused' && pauseStartTime) {
      totalPauseTime += (now - pauseStartTime);
    }

    const totalWorkTime = Math.floor((now - startTime - totalPauseTime) / (1000 * 60)); // 分単位

    // 作業記録を更新
    const updatedRecord = await window.aivicApi.update(1, currentWorkRecord.作業記録ID, {
      作業終了時刻: now.toISOString(),
      作業時間: totalWorkTime,
      進捗状況: '完了',
      更新日時: now.toISOString()
    });

    if (updatedRecord) {
      updateWorkStatus('completed');

      // タイマー停止
      if (timerInterval) {
        clearInterval(timerInterval);
        timerInterval = null;
      }

      // リセット
      startTime = null;
      pauseStartTime = null;
      totalPauseTime = 0;
      currentWorkRecord = null;

      // 履歴更新
      const records = await window.aivicApi.list(1);
      if (records) renderTodayHistory(records);

      alert(`作業が完了しました。作業時間: ${Math.floor(totalWorkTime / 60)}時間${totalWorkTime % 60}分`);
    }
  }

  // 保存
  async function saveWork() {
    const workItemId = container.querySelector('#work-item-select').value;
    const workLocation = container.querySelector('#work-location').value.trim();
    const workContent = container.querySelector('#work-content').value.trim();
    const workMemo = container.querySelector('#work-memo').value.trim();

    if (!workItemId) {
      alert('作業項目を選択してください');
      return;
    }

    if (!workLocation) {
      alert('作業場所を入力してください');
      return;
    }

    if (!workContent) {
      alert('作業内容を入力してください');
      return;
    }

    if (currentWorkRecord) {
      // 作業中の記録を更新
      const updated = await window.aivicApi.update(1, currentWorkRecord.作業記録ID, {
        作業場所: workLocation,
        作業内容: workContent,
        備考: workMemo,
        更新日時: new Date().toISOString()
      });

      if (updated) {
        alert('作業記録を更新しました');
        const records = await window.aivicApi.list(1);
        if (records) renderTodayHistory(records);
      }
    } else {
      alert('作業記録を保存するには、まず作業を開始してください');
    }
  }

  // キャンセル
  function cancelWork() {
    if (currentWorkRecord || workStatus !== 'waiting') {
      if (!confirm('未保存の変更があります。キャンセルしますか？')) {
        return;
      }
    }

    // フォームクリア
    container.querySelector('#work-item-select').value = '';
    container.querySelector('#work-location').value = '';
    container.querySelector('#work-content').value = '';
    container.querySelector('#work-memo').value = '';

    // 作業中の場合はリセット
    if (currentWorkRecord) {
      if (timerInterval) {
        clearInterval(timerInterval);
        timerInterval = null;
      }
      startTime = null;
      pauseStartTime = null;
      totalPauseTime = 0;
      currentWorkRecord = null;
      updateWorkStatus('waiting');
      container.querySelector('#elapsed-time').textContent = '00:00:00';
    }
  }

  // 文字数カウンター
  function setupCharacterCounter(textareaId, counterId) {
    const textarea = container.querySelector(`#${textareaId}`);
    const counter = container.querySelector(`#${counterId}`);

    textarea.addEventListener('input', () => {
      const length = textarea.value.length;
      const maxLength = textarea.getAttribute('maxlength') || 500;
      counter.textContent = `${length}/${maxLength}`;
    });
  }

  // 初期化
  updateCurrentTime();
  setInterval(updateCurrentTime, 1000);
  updateWorkStatus('waiting');

  // 作業項目マスタ読み込み
  loadWorkItems();

  // 本日の作業履歴読み込み
  window.aivicApi.list(1).then(records => {
    if (records) renderTodayHistory(records);
  });

  // 文字数カウンター設定
  setupCharacterCounter('work-memo', 'memo-counter');
  setupCharacterCounter('pause-reason-detail', 'pause-reason-counter');

  // イベントリスナー
  container.querySelector('#start-work-btn').addEventListener('click', startWork);
  container.querySelector('#pause-work-btn').addEventListener('click', pauseWork);
  container.querySelector('#end-work-btn').addEventListener('click', endWork);
  container.querySelector('#save-work-btn').addEventListener('click', saveWork);
  container.querySelector('#cancel-work-btn').addEventListener('click', cancelWork);

  // 中断モーダル
  container.querySelector('#pause-confirm-btn').addEventListener('click', executePause);
  container.querySelector('#pause-cancel-btn').addEventListener('click', () => {
    container.querySelector('#pause-modal').style.display = 'none';
    container.querySelector('#pause-reason-category').value = '';
    container.querySelector('#pause-reason-detail').value = '';
  });

  // 編集ボタン
  container.addEventListener('click', async (e) => {
    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      const recordId = editBtn.dataset.id;
      // 編集機能は別画面で実装される想定
      alert('編集機能は作業履歴画面で実装されます');
    }
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#work-history-tbody");
  const resultCount = container.querySelector("#result-count");
  const noResults = container.querySelector("#no-results");
  const errorMessage = container.querySelector("#error-message");
  const tableWrap = container.querySelector(".table-wrap");

  let allWorkRecords = [];
  let allWorkItems = [];
  let allInterruptions = [];

  // 作業項目マスタを読み込んでドロップダウンに設定
  async function loadWorkItems() {
    const workItemsTable = tables.find(t => t.tableName === "作業項目マスタ");
    if (workItemsTable) {
      const workItemsIndex = tables.indexOf(workItemsTable);
      const items = await window.aivicApi.list(workItemsIndex);
      if (items) {
        allWorkItems = items;
        const select = container.querySelector("#filter-work-item");
        select.innerHTML = '<option value="">すべて</option>' + 
          items.map(item => `<option value="${item.作業項目名}">${item.作業項目名}</option>`).join("");
      }
    }
  }

  // 中断記録を読み込み
  async function loadInterruptions() {
    const interruptionsTable = tables.find(t => t.tableName === "中断記録");
    if (interruptionsTable) {
      const interruptionsIndex = tables.indexOf(interruptionsTable);
      const interruptions = await window.aivicApi.list(interruptionsIndex);
      if (interruptions) {
        allInterruptions = interruptions;
      }
    }
  }

  // 中断回数を計算
  function getInterruptionCount(workRecordId) {
    return allInterruptions.filter(int => int.作業記録ID === workRecordId).length;
  }

  // 時間フォーマット
  function formatTime(dateStr) {
    if (!dateStr) return "-";
    const date = new Date(dateStr);
    return date.toLocaleTimeString("ja-JP", { hour: "2-digit", minute: "2-digit" });
  }

  // 作業時間フォーマット（分 → 時間:分）
  function formatWorkTime(minutes) {
    if (!minutes) return "-";
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}:${mins.toString().padStart(2, '0')}`;
  }

  // 日付フォーマット
  function formatDate(dateStr) {
    if (!dateStr) return "-";
    const date = new Date(dateStr);
    return date.toLocaleDateString("ja-JP");
  }

  // エラー表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = "block";
    setTimeout(() => {
      errorMessage.style.display = "none";
    }, 5000);
  }

  // テーブル再描画
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = "";
      resultCount.textContent = "0";
      noResults.style.display = "block";
      tableWrap.style.display = "none";
      return;
    }

    noResults.style.display = "none";
    tableWrap.style.display = "block";
    resultCount.textContent = rows.length;

    tbody.innerHTML = rows.map(row => {
      const interruptCount = getInterruptionCount(row.作業記録ID);
      return `
        <tr data-id="${row.作業記録ID}" style="border-bottom: 1px solid var(--border); height: 36px;">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatDate(row.作業日)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${row.作業種別 || "-"}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatTime(row.作業開始時刻)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatTime(row.作業終了時刻)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); text-align: right;">${formatWorkTime(row.作業時間)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); text-align: right;">${interruptCount}</td>
          <td style="padding: 6px 10px; text-align: center;">
            <button class="action-btn secondary detail-btn" data-id="${row.作業記録ID}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 12px; cursor: pointer;">詳細確認</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // フィルタリング
  function filterRecords() {
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;
    const workItem = container.querySelector("#filter-work-item").value;
    const status = container.querySelector("#filter-status").value;

    // 日付バリデーション
    if (startDate && endDate) {
      const start = new Date(startDate);
      const end = new Date(endDate);
      const today = new Date();
      today.setHours(23, 59, 59, 999);

      if (start > end) {
        showError("開始日は終了日より前の日付を入力してください");
        return;
      }

      if (start > today || end > today) {
        showError("未来の日付は選択できません");
        return;
      }

      const diffTime = Math.abs(end - start);
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      if (diffDays > 365) {
        showError("1年以上の期間は選択できません");
        return;
      }
    }

    let filtered = allWorkRecords.filter(record => {
      // 日付フィルター
      if (startDate) {
        const recordDate = new Date(record.作業日);
        const filterStart = new Date(startDate);
        if (recordDate < filterStart) return false;
      }

      if (endDate) {
        const recordDate = new Date(record.作業日);
        const filterEnd = new Date(endDate);
        filterEnd.setHours(23, 59, 59, 999);
        if (recordDate > filterEnd) return false;
      }

      // 作業項目フィルター
      if (workItem && record.作業種別 !== workItem) return false;

      // 状況フィルター
      if (status && record.進捗状況 !== status) return false;

      return true;
    });

    // 作業日時の降順でソート
    filtered.sort((a, b) => new Date(b.作業日) - new Date(a.作業日));

    renderRows(filtered);
  }

  // CSVエクスポート
  function exportCSV() {
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;
    const workItem = container.querySelector("#filter-work-item").value;
    const status = container.querySelector("#filter-status").value;

    let filtered = allWorkRecords;

    if (startDate || endDate || workItem || status) {
      filtered = allWorkRecords.filter(record => {
        if (startDate && new Date(record.作業日) < new Date(startDate)) return false;
        if (endDate) {
          const filterEnd = new Date(endDate);
          filterEnd.setHours(23, 59, 59, 999);
          if (new Date(record.作業日) > filterEnd) return false;
        }
        if (workItem && record.作業種別 !== workItem) return false;
        if (status && record.進捗状況 !== status) return false;
        return true;
      });
    }

    const headers = ["作業日時", "作業項目名", "開始時刻", "終了時刻", "作業時間", "中断回数", "作業場所", "作業内容", "進捗状況"];
    const csvContent = [
      headers.join(","),
      ...filtered.map(row => {
        const interruptCount = getInterruptionCount(row.作業記録ID);
        return [
          `"${formatDate(row.作業日)}"`,
          `"${row.作業種別 || ""}"`,
          `"${formatTime(row.作業開始時刻)}"`,
          `"${formatTime(row.作業終了時刻)}"`,
          `"${formatWorkTime(row.作業時間)}"`,
          interruptCount,
          `"${row.作業場所 || ""}"`,
          `"${(row.作業内容 || "").replace(/"/g, '""')}"`,
          `"${row.進捗状況 || ""}"`
        ].join(",");
      })
    ].join("\n");

    const bom = "\uFEFF";
    const blob = new Blob([bom + csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `作業履歴_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadInitialData() {
    await loadWorkItems();
    await loadInterruptions();

    const workRecordsTable = tables.find(t => t.tableName === "作業記録");
    if (workRecordsTable) {
      const workRecordsIndex = tables.indexOf(workRecordsTable);
      const records = await window.aivicApi.list(workRecordsIndex);
      if (records) {
        allWorkRecords = records;
        filterRecords();
      } else {
        renderRows([]);
      }
    } else {
      renderRows([]);
    }
  }

  // イベントリスナー
  container.querySelector("#btn-search").addEventListener("click", filterRecords);

  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#filter-start-date").value = "";
    container.querySelector("#filter-end-date").value = "";
    container.querySelector("#filter-work-item").value = "";
    container.querySelector("#filter-status").value = "";
    renderRows(allWorkRecords.sort((a, b) => new Date(b.作業日) - new Date(a.作業日)));
  });

  container.querySelector("#btn-csv-export").addEventListener("click", exportCSV);

  container.querySelector("#btn-data-extract").addEventListener("click", () => {
    window.showScreen("scr-1778907353387");
  });

  container.querySelector("#btn-back").addEventListener("click", () => {
    window.showScreen("scr-1778907133295");
  });

  // 行レベル操作
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      window.showScreen("scr-1778907367889");
    }
  });

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  let currentUser = { id: 'user-001', name: '田中太郎' };
  let workItems = [];
  let activeWorks = [];
  let suspendedWorks = [];
  let resumeTargetId = null;

  // 現在日時を更新する関数
  function updateCurrentTime() {
    const now = new Date();
    const formatted = `${now.getFullYear()}/${String(now.getMonth() + 1).padStart(2, '0')}/${String(now.getDate()).padStart(2, '0')} ${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
    container.querySelector('#current-datetime').textContent = formatted;
  }

  // 作業項目ドロップダウンを更新
  function updateWorkItemSelect() {
    const select = container.querySelector('#work-item-select');
    select.innerHTML = '<option value="">作業項目を選択してください</option>';
    workItems.forEach(item => {
      if (item.有効フラグ) {
        const option = document.createElement('option');
        option.value = item.作業項目ID;
        option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
        select.appendChild(option);
      }
    });
  }

  // 進行中作業一覧を描画
  function renderActiveWorks() {
    const container_el = container.querySelector('#active-works-container');
    if (activeWorks.length === 0) {
      container_el.innerHTML = '<div style="color: var(--text-muted); font-size: 12px; text-align: center; padding: 16px;">進行中の作業はありません</div>';
      return;
    }

    const html = activeWorks.map(work => {
      const startTime = new Date(work.作業開始時刻);
      const elapsed = Math.floor((Date.now() - startTime.getTime()) / 1000 / 60);
      const hours = Math.floor(elapsed / 60);
      const minutes = elapsed % 60;
      const elapsedText = hours > 0 ? `${hours}時間${minutes}分` : `${minutes}分`;

      return `
        <div style="padding: 8px 12px; border: 1px solid var(--border); border-radius: 6px; margin-bottom: 8px;">
          <div style="display: flex; justify-content: space-between; align-items: center;">
            <div>
              <div style="font-size: 13px; font-weight: 500; color: var(--text);">${work.プロジェクト名}</div>
              <div style="font-size: 11px; color: var(--text-muted);">
                開始: ${startTime.getHours().toString().padStart(2, '0')}:${startTime.getMinutes().toString().padStart(2, '0')} | 
                経過: ${elapsedText}
              </div>
            </div>
            <button class="action-btn" onclick="window.showScreen('scr-1778907296658')" style="padding: 4px 8px; font-size: 11px;">
              工数入力
            </button>
          </div>
        </div>
      `;
    }).join('');

    container_el.innerHTML = html;
  }

  // 中断中作業一覧を描画
  function renderSuspendedWorks() {
    const container_el = container.querySelector('#suspended-works-container');
    if (suspendedWorks.length === 0) {
      container_el.innerHTML = '<div style="color: var(--text-muted); font-size: 12px; text-align: center; padding: 16px;">中断中の作業はありません</div>';
      return;
    }

    const html = suspendedWorks.map(work => {
      const startTime = new Date(work.作業開始時刻);

      return `
        <div style="padding: 8px 12px; border: 1px solid var(--border); border-radius: 6px; margin-bottom: 8px;">
          <div style="display: flex; justify-content: space-between; align-items: center;">
            <div>
              <div style="font-size: 13px; font-weight: 500; color: var(--text);">${work.プロジェクト名}</div>
              <div style="font-size: 11px; color: var(--text-muted);">
                開始: ${startTime.getHours().toString().padStart(2, '0')}:${startTime.getMinutes().toString().padStart(2, '0')} | 
                場所: ${work.作業場所}
              </div>
            </div>
            <button class="action-btn resume-work-btn" data-id="${work.作業記録ID}" style="padding: 4px 8px; font-size: 11px;">
              再開
            </button>
          </div>
        </div>
      `;
    }).join('');

    container_el.innerHTML = html;
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorEl = container.querySelector('#error-message');
    errorEl.textContent = message;
    errorEl.classList.remove('hidden');
    setTimeout(() => {
      errorEl.classList.add('hidden');
    }, 5000);
  }

  // フォームクリア
  function clearForm() {
    container.querySelector('#work-item-select').value = '';
    container.querySelector('#work-location-input').value = '';
    container.querySelector('#work-notes-input').value = '';
    container.querySelector('#notes-counter').textContent = '0';
  }

  // バリデーション
  function validateForm() {
    const workItemId = container.querySelector('#work-item-select').value;
    const workLocation = container.querySelector('#work-location-input').value.trim();

    if (!workItemId) {
      showError('作業項目を選択してください');
      return false;
    }

    if (!workLocation) {
      showError('作業場所を入力してください');
      return false;
    }

    // 複数作業の同時開始制御
    if (activeWorks.length > 0) {
      showError('既に実行中の作業があります。同時に複数の作業を開始することはできません。');
      return false;
    }

    // 不正文字チェック（基本的なXSS対策）
    if (workLocation.includes('<script>') || workLocation.includes('</script>')) {
      showError('作業場所に不正な文字が含まれています');
      return false;
    }

    return true;
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 作業項目マスタを取得
      const workItemsData = await window.aivicApi.list(3);
      if (workItemsData) {
        workItems = workItemsData;
        updateWorkItemSelect();
      }

      // 作業記録を取得して進行中・中断中を分類
      const workRecords = await window.aivicApi.list(1);
      if (workRecords) {
        activeWorks = workRecords.filter(record => 
          record.作業員ID === currentUser.id && record.進捗状況 === '作業中'
        );
        suspendedWorks = workRecords.filter(record => 
          record.作業員ID === currentUser.id && record.進捗状況 === '中断'
        );
        renderActiveWorks();
        renderSuspendedWorks();
      }
    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
    }
  }

  // 作業開始処理
  async function startWork() {
    if (!validateForm()) return;

    const workItemId = container.querySelector('#work-item-select').value;
    const workLocation = container.querySelector('#work-location-input').value.trim();
    const notes = container.querySelector('#work-notes-input').value.trim();

    const selectedWorkItem = workItems.find(item => item.作業項目ID === workItemId);

    const workRecord = {
      作業員ID: currentUser.id,
      作業日: new Date().toISOString(),
      作業開始時刻: new Date().toISOString(),
      作業終了時刻: null,
      作業時間: null,
      プロジェクト名: selectedWorkItem.作業項目名,
      作業場所: workLocation,
      作業種別: selectedWorkItem.カテゴリ || '一般作業',
      作業内容: notes || selectedWorkItem.作業項目説明 || '',
      進捗状況: '作業中',
      備考: notes,
      承認状態: '未承認',
      承認者ID: null,
      承認日時: null,
      作成者ID: currentUser.id
    };

    try {
      const saved = await window.aivicApi.save(1, workRecord);
      if (saved) {
        clearForm();
        await loadInitialData(); // データを再読み込み
        // 工数入力画面に遷移
        window.showScreen('scr-1778907296658');
      }
    } catch (error) {
      showError('作業開始の登録に失敗しました');
    }
  }

  // 作業再開処理
  async function resumeWork(workId) {
    try {
      const updated = await window.aivicApi.update(1, workId, {
        進捗状況: '作業中',
        作業開始時刻: new Date().toISOString() // 再開時刻で更新
      });

      if (updated) {
        await loadInitialData();
        container.querySelector('#resume-dialog').classList.add('hidden');
        window.showScreen('scr-1778907296658');
      }
    } catch (error) {
      showError('作業再開に失敗しました');
    }
  }

  // イベントリスナー設定
  container.querySelector('#btn-start-work').addEventListener('click', startWork);

  container.querySelector('#btn-clear').addEventListener('click', clearForm);

  container.querySelector('#btn-logout').addEventListener('click', () => {
    if (confirm('ログアウトしますか？')) {
      window.location.href = './login.html';
    }
  });

  container.querySelector('#btn-settings').addEventListener('click', () => {
    // 設定画面への遷移（画面IDは仮）
    alert('設定画面は未実装です');
  });

  // 備考文字数カウンター
  container.querySelector('#work-notes-input').addEventListener('input', (e) => {
    const length = e.target.value.length;
    container.querySelector('#notes-counter').textContent = length;
  });

  // 作業再開ダイアログ関連
  container.addEventListener('click', (e) => {
    const resumeBtn = e.target.closest('.resume-work-btn');
    if (resumeBtn) {
      const workId = resumeBtn.dataset.id;
      const work = suspendedWorks.find(w => w.作業記録ID === workId);

      if (!work) {
        showError('指定された作業が見つかりません');
        return;
      }

      resumeTargetId = workId;
      container.querySelector('#resume-dialog-text').textContent = `「${work.プロジェクト名}」の作業を再開しますか？`;
      container.querySelector('#resume-dialog').classList.remove('hidden');
    }
  });

  container.querySelector('#resume-confirm-btn').addEventListener('click', () => {
    if (resumeTargetId) {
      resumeWork(resumeTargetId);
    }
  });

  container.querySelector('#resume-cancel-btn').addEventListener('click', () => {
    container.querySelector('#resume-dialog').classList.add('hidden');
    resumeTargetId = null;
  });

  // 初期化
  updateCurrentTime();
  setInterval(updateCurrentTime, 60000); // 1分ごとに時刻更新

  // 初期データがある場合は即座に表示
