    workItems = tables[3].records;
    updateWorkItemSelect();
  }

  if (tables[1] && tables[1].records) {
    const workRecords = tables[1].records;
    activeWorks = workRecords.filter(record => 
      record.作業員ID === currentUser.id && record.進捗状況 === '作業中'
    );
    suspendedWorks = workRecords.filter(record => 
      record.作業員ID === currentUser.id && record.進捗状況 === '中断'
    );
    renderActiveWorks();
    renderSuspendedWorks();
  }

  // 最新データを読み込み
  loadInitialData();
}

function(container, apiUrl, tables) {
  // 現在の作業記録データを取得（最新の未完了記録を想定）
  let currentWorkRecord = null;
  let breakRecords = [];

  // 初期データの設定
  async function loadCurrentWorkRecord() {
    try {
      const workRecords = await window.aivicApi.list(1); // 作業記録テーブル
      if (workRecords) {
        // 最新の未完了記録を取得
        currentWorkRecord = workRecords.find(r => !r.作業終了時刻) || workRecords[workRecords.length - 1];

        if (currentWorkRecord) {
          // 中断記録を取得
          const allBreakRecords = await window.aivicApi.list(2); // 中断記録テーブル
          if (allBreakRecords) {
            breakRecords = allBreakRecords.filter(b => b.作業記録ID === currentWorkRecord.作業記録ID);
          }

          // 作業項目名を取得
          const workItems = await window.aivicApi.list(3); // 作業項目マスタ
          const workItem = workItems?.find(w => w.作業項目ID === currentWorkRecord.作業項目ID);

          updateTimeDisplay();
          updateWorkItemDisplay(workItem?.作業項目名 || currentWorkRecord.作業内容);
        }
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 時刻表示の更新
  function updateTimeDisplay() {
    if (!currentWorkRecord) return;

    const startTime = new Date(currentWorkRecord.作業開始時刻);
    const endTime = currentWorkRecord.作業終了時刻 ? new Date(currentWorkRecord.作業終了時刻) : new Date();

    // 開始時刻表示
    container.querySelector('#start-time-display').textContent = formatTime(startTime);

    // 終了時刻表示
    container.querySelector('#end-time-display').textContent = formatTime(endTime);

    // 総作業時間計算
    const totalMinutes = Math.floor((endTime - startTime) / (1000 * 60));
    container.querySelector('#total-time-display').textContent = formatDuration(totalMinutes);

    // 中断時間計算
    const breakMinutes = breakRecords.reduce((total, record) => {
      if (record.中断時間) {
        return total + record.中断時間;
      }
      return total;
    }, 0);
    container.querySelector('#break-time-display').textContent = formatDuration(breakMinutes);

    // 実作業時間計算
    const actualWorkMinutes = totalMinutes - breakMinutes;
    container.querySelector('#actual-work-time-display').textContent = formatDuration(actualWorkMinutes);
  }

  // 作業項目表示の更新
  function updateWorkItemDisplay(itemName) {
    container.querySelector('#work-item-display').textContent = itemName || '作業項目未設定';
  }

  // 時刻フォーマット（HH:mm）
  function formatTime(date) {
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  // 時間フォーマット（H:mm）
  function formatDuration(minutes) {
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}:${mins.toString().padStart(2, '0')}`;
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
  }

  // エラーメッセージ非表示
  function hideError() {
    container.querySelector('#error-message').style.display = 'none';
  }

  // バリデーション
  function validateForm() {
    hideError();

    const completionStatus = container.querySelector('#completion-status').value;
    const hasIssue = container.querySelector('#has-issue').checked;
    const issueContent = container.querySelector('#issue-content').value.trim();
    const workMemo = container.querySelector('#work-memo').value.trim();

    // 完了状況必須チェック
    if (!completionStatus) {
      showError('完了状況を選択してください。');
      return false;
    }

    // 異常報告チェック時の異常内容必須チェック
    if (hasIssue && !issueContent) {
      showError('異常・問題が発生した場合は、異常内容を入力してください。');
      return false;
    }

    // 文字数チェック
    if (workMemo.length > 1000) {
      showError('作業メモは1000文字以内で入力してください。');
      return false;
    }

    if (issueContent.length > 500) {
      showError('異常内容は500文字以内で入力してください。');
      return false;
    }

    return true;
  }

  // 初期化処理
  loadCurrentWorkRecord();

  // 異常報告チェックボックスの制御
  container.querySelector('#has-issue').addEventListener('change', function() {
    const issueSection = container.querySelector('#issue-content-section');
    const issueContent = container.querySelector('#issue-content');

    if (this.checked) {
      issueSection.style.display = 'block';
    } else {
      issueSection.style.display = 'none';
      issueContent.value = '';
      container.querySelector('#issue-count').textContent = '0';
    }
  });

  // 文字数カウント
  container.querySelector('#work-memo').addEventListener('input', function() {
    container.querySelector('#memo-count').textContent = this.value.length;
  });

  container.querySelector('#issue-content').addEventListener('input', function() {
    container.querySelector('#issue-count').textContent = this.value.length;
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', function() {
    if (confirm('入力内容が破棄されますが、よろしいですか？')) {
      history.back();
    }
  });

  // 記録確定ボタン
  container.querySelector('#btn-confirm').addEventListener('click', async function() {
    if (!validateForm()) return;
    if (!currentWorkRecord) {
      showError('作業記録が見つかりません。');
      return;
    }

    try {
      const workMemo = container.querySelector('#work-memo').value.trim();
      const completionStatus = container.querySelector('#completion-status').value;
      const hasIssue = container.querySelector('#has-issue').checked;
      const issueContent = container.querySelector('#issue-content').value.trim();

      // 作業記録を更新
      const updateData = {
        作業終了時刻: new Date().toISOString(),
        進捗状況: completionStatus,
        備考: workMemo,
        承認状態: '未承認'
      };

      // 作業時間を計算して更新
      const startTime = new Date(currentWorkRecord.作業開始時刻);
      const endTime = new Date();
      const totalMinutes = Math.floor((endTime - startTime) / (1000 * 60));
      const breakMinutes = breakRecords.reduce((total, record) => total + (record.中断時間 || 0), 0);
      updateData.作業時間 = totalMinutes - breakMinutes;

      const updatedRecord = await window.aivicApi.update(1, currentWorkRecord.作業記録ID, updateData);

      if (updatedRecord) {
        // 異常報告がある場合は異常値検出ログに記録
        if (hasIssue && issueContent) {
          await window.aivicApi.save(4, {
            検出対象テーブル: '作業記録',
            検出対象レコードID: currentWorkRecord.作業記録ID,
            ユーザーID: currentWorkRecord.作業員ID,
            異常値種別: '作業中異常報告',
            検出項目: '異常内容',
            検出値: issueContent,
            閾値: '手動報告',
            重要度: '中',
            確認状況: '未確認',
            通知送信フラグ: true,
            検出日時: new Date().toISOString()
          });
        }

        // 成功メッセージ表示
        alert('工数記録が正常に確定されました。');

        // ボタン表示切り替え
        container.querySelector('#btn-confirm').style.display = 'none';
        container.querySelector('#btn-cancel').style.display = 'none';
        container.querySelector('#btn-view-record').style.display = 'inline-block';

        // フォーム無効化
        container.querySelector('#work-memo').disabled = true;
        container.querySelector('#completion-status').disabled = true;
        container.querySelector('#has-issue').disabled = true;
        container.querySelector('#issue-content').disabled = true;
      }
    } catch (error) {
      console.error('記録確定エラー:', error);
      showError('記録確定中にエラーが発生しました。もう一度お試しください。');
    }
  });

  // 記録確認ボタン
  container.querySelector('#btn-view-record').addEventListener('click', function() {
    window.showScreen("scr-1778907226171");
  });

  // ホバー効果
  container.querySelector('#btn-confirm').addEventListener('mouseenter', function() {
    this.style.background = 'var(--primary-hover)';
  });

  container.querySelector('#btn-confirm').addEventListener('mouseleave', function() {
    this.style.background = 'var(--primary)';
  });

  container.querySelector('#btn-cancel').addEventListener('mouseenter', function() {
    this.style.background = 'rgba(255,255,255,0.05)';
  });

  container.querySelector('#btn-cancel').addEventListener('mouseleave', function() {
    this.style.background = 'transparent';
  });

  // フォーカス効果
  const inputs = container.querySelectorAll('input, select, textarea');
  inputs.forEach(input => {
    input.addEventListener('focus', function() {
      this.style.outline = 'none';
      this.style.borderColor = 'var(--primary)';
      this.style.boxShadow = '0 0 0 2px rgba(255,255,255,0.08)';
    });

    input.addEventListener('blur', function() {
      this.style.borderColor = 'rgba(255,255,255,0.18)';
      this.style.boxShadow = 'none';
    });
  });
}

function(container, apiUrl, tables) {
  let autoSaveInterval = null;
  let currentSaveIntervalSeconds = 30;
  let localData = JSON.parse(localStorage.getItem('workRecordsLocal') || '[]');
  let isOnline = navigator.onLine;
  let lastSaveTime = localStorage.getItem('lastAutoSaveTime');

  // ローカルデータ再描画
  function renderLocalData() {
    const tbody = container.querySelector('#local-data-tbody');
    if (localData.length === 0) {
      tbody.innerHTML = '<tr><td colspan="5" style="padding: 12px; text-align: center; color: var(--text-muted); font-size: 12px;">ローカル保存データはありません</td></tr>';
      return;
    }

    tbody.innerHTML = localData.map((item, index) => `
      <tr data-index="${index}">
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${new Date(item.作業日).toLocaleString()}</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${item.プロジェクト名 || '-'}</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${(item.作業内容 || '').substring(0, 30)}${item.作業内容?.length > 30 ? '...' : ''}</td>
        <td style="padding: 6px 10px; font-size: 12px;">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; ${item.synced ? 'background: rgba(34, 197, 94, 0.2); color: #22c55e;' : 'background: rgba(251, 191, 36, 0.2); color: #fbbf24;'}">
            ${item.synced ? '同期済み' : '未同期'}
          </span>
        </td>
        <td style="padding: 6px 10px;">
          <button class="retry-sync-btn action-btn secondary" data-index="${index}" ${item.synced ? 'disabled' : ''} 
                  style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 2px 6px; border-radius: 4px; font-size: 11px; cursor: ${item.synced ? 'not-allowed' : 'pointer'}; opacity: ${item.synced ? '0.5' : '1'};">
            再同期
          </button>
        </td>
      </tr>
    `).join('');

    // 同期待ち件数更新
    const pendingCount = localData.filter(item => !item.synced).length;
    container.querySelector('#pending-count').textContent = `${pendingCount} 件`;
  }

  // ネットワーク状態更新
  function updateNetworkStatus() {
    const indicator = container.querySelector('#network-indicator');
    const status = container.querySelector('#network-status');

    if (isOnline) {
      indicator.style.background = '#22c55e';
      status.textContent = 'オンライン';
    } else {
      indicator.style.background = '#ef4444';
      status.textContent = 'オフライン';
    }
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-notification');
    const errorMessage = container.querySelector('#error-message');
    errorMessage.textContent = message;
    errorDiv.classList.remove('hidden');

    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // 自動保存処理
  function performAutoSave() {
    // 実際の作業記録データを取得してローカル保存をシミュレート
    const now = new Date();
    const mockWorkRecord = {
      id: 'local_' + Date.now(),
      作業日: now.toISOString(),
      プロジェクト名: 'サンプルプロジェクト',
      作業内容: '自動保存されたデータ',
      synced: false,
      timestamp: now.getTime()
    };

    // 実際のアプリでは現在入力中のフォームデータを保存
    if (Math.random() > 0.9) { // 10%の確率でエラーをシミュレート
      showError('自動保存に失敗しました。ストレージ容量を確認してください。');
      return;
    }

    localData.push(mockWorkRecord);
    localStorage.setItem('workRecordsLocal', JSON.stringify(localData));

    const saveTime = now.toLocaleTimeString();
    container.querySelector('#last-save-time').textContent = saveTime;
    localStorage.setItem('lastAutoSaveTime', saveTime);

    renderLocalData();
  }

  // 自動保存開始
  function startAutoSave() {
    if (autoSaveInterval) {
      clearInterval(autoSaveInterval);
    }

    autoSaveInterval = setInterval(performAutoSave, currentSaveIntervalSeconds * 1000);

    const indicator = container.querySelector('#auto-save-indicator');
    const status = container.querySelector('#auto-save-status');
    indicator.style.background = '#22c55e';
    status.textContent = `正常動作中 (${currentSaveIntervalSeconds}秒間隔)`;
  }

  // 手動同期処理
  async function performManualSync() {
    const unsyncedData = localData.filter(item => !item.synced);
    if (unsyncedData.length === 0) {
      showError('同期待ちのデータがありません。');
      return;
    }

    if (!isOnline) {
      showError('オフライン状態のため同期できません。');
      return;
    }

    // 同期進行状況表示
    const modal = container.querySelector('#sync-progress-modal');
    const progressBar = container.querySelector('#sync-progress-bar');
    const progressText = container.querySelector('#sync-progress-text');

    modal.classList.remove('hidden');

    let syncedCount = 0;
    const totalCount = unsyncedData.length;

    for (let i = 0; i < unsyncedData.length; i++) {
      const item = unsyncedData[i];

      try {
        // 作業記録テーブル（tableIndex: 1）に保存
        const workRecord = {
          作業員ID: 'current-user-id',
          作業日: item.作業日,
          作業開始時刻: item.作業日,
          作業終了時刻: new Date(new Date(item.作業日).getTime() + 3600000).toISOString(),
          作業時間: 60,
          プロジェクト名: item.プロジェクト名,
          作業場所: '現場A',
          作業種別: '通常作業',
          作業内容: item.作業内容,
          進捗状況: '完了',
          承認状態: '未承認',
          作成者ID: 'current-user-id'
        };

        const saved = await window.aivicApi.save(1, workRecord);
        if (saved) {
          // ローカルデータの同期フラグを更新
          const localIndex = localData.findIndex(local => local.id === item.id);
          if (localIndex !== -1) {
            localData[localIndex].synced = true;
          }
          syncedCount++;
        }
      } catch (error) {
        console.error('同期エラー:', error);
      }

      // 進行状況更新
      const progress = ((i + 1) / totalCount) * 100;
      progressBar.style.width = `${progress}%`;
      progressText.textContent = `${syncedCount} / ${totalCount} 件完了`;

      // 少し待機してUIを更新
      await new Promise(resolve => setTimeout(resolve, 100));
    }

    localStorage.setItem('workRecordsLocal', JSON.stringify(localData));
    renderLocalData();

    setTimeout(() => {
      modal.classList.add('hidden');
      if (syncedCount === totalCount) {
        alert(`${syncedCount}件のデータを正常に同期しました。`);
      } else {
        showError(`${syncedCount}/${totalCount}件の同期が完了しました。一部失敗したデータがあります。`);
      }
    }, 500);
  }

  // データ復旧処理
  function performDataRecovery() {
    const recoveryData = localStorage.getItem('emergencyBackup');
    if (!recoveryData) {
      showError('復旧可能なデータが見つかりません。');
      return;
    }

    try {
      const backupData = JSON.parse(recoveryData);
      if (confirm(`${backupData.length}件のバックアップデータが見つかりました。復旧しますか？`)) {
        localData = [...localData, ...backupData];
        localStorage.setItem('workRecordsLocal', JSON.stringify(localData));
        localStorage.removeItem('emergencyBackup');
        renderLocalData();
        alert('データの復旧が完了しました。');
      }
    } catch (error) {
      showError('バックアップデータの読み込みに失敗しました。');
    }
  }

  // 初期化
  renderLocalData();
  updateNetworkStatus();

  if (lastSaveTime) {
    container.querySelector('#last-save-time').textContent = lastSaveTime;
  }

  startAutoSave();

  // イベントリスナー
  container.querySelector('#btn-save-settings').addEventListener('click', () => {
    const intervalInput = container.querySelector('#save-interval');
    const newInterval = parseInt(intervalInput.value);

    if (newInterval < 1) {
      showError('保存間隔は1秒以上で設定してください。');
      return;
    }

    if (newInterval > 86400) {
      showError('保存間隔は86400秒以下で設定してください。');
      return;
    }

    currentSaveIntervalSeconds = newInterval;
    localStorage.setItem('autoSaveInterval', newInterval.toString());
    startAutoSave();
    alert('保存設定を更新しました。');
  });

  container.querySelector('#btn-manual-sync').addEventListener('click', performManualSync);
  container.querySelector('#btn-data-recovery').addEventListener('click', performDataRecovery);

  container.querySelector('#btn-clear-local').addEventListener('click', () => {
    if (confirm('ローカル保存データをすべて削除しますか？未同期のデータは失われます。')) {
      localData = [];
      localStorage.removeItem('workRecordsLocal');
      renderLocalData();
    }
  });

  // 個別再同期
  container.addEventListener('click', async (e) => {
    const retryBtn = e.target.closest('.retry-sync-btn');
    if (retryBtn && !retryBtn.disabled) {
      const index = parseInt(retryBtn.dataset.index);
      const item = localData[index];

      if (!isOnline) {
        showError('オフライン状態のため同期できません。');
        return;
      }

      try {
        const workRecord = {
          作業員ID: 'current-user-id',
          作業日: item.作業日,
          作業開始時刻: item.作業日,
          作業終了時刻: new Date(new Date(item.作業日).getTime() + 3600000).toISOString(),
          作業時間: 60,
          プロジェクト名: item.プロジェクト名,
          作業場所: '現場A',
          作業種別: '通常作業',
          作業内容: item.作業内容,
          進捗状況: '完了',
          承認状態: '未承認',
          作成者ID: 'current-user-id'
        };

        const saved = await window.aivicApi.save(1, workRecord);
        if (saved) {
          localData[index].synced = true;
          localStorage.setItem('workRecordsLocal', JSON.stringify(localData));
          renderLocalData();
          alert('データを同期しました。');
        } else {
          showError('同期に失敗しました。');
        }
      } catch (error) {
        showError('同期処理中にエラーが発生しました。');
      }
    }
  });

  // ネットワーク状態監視
  window.addEventListener('online', () => {
    isOnline = true;
    updateNetworkStatus();

    // オンライン復旧時の自動同期
    const unsyncedData = localData.filter(item => !item.synced);
    if (unsyncedData.length > 0) {
      setTimeout(() => {
        if (confirm(`${unsyncedData.length}件の未同期データがあります。自動同期しますか？`)) {
          performManualSync();
        }
      }, 1000);
    }
  });

  window.addEventListener('offline', () => {
    isOnline = false;
    updateNetworkStatus();
  });

  // 設定値復元
  const savedInterval = localStorage.getItem('autoSaveInterval');
  if (savedInterval) {
    currentSaveIntervalSeconds = parseInt(savedInterval);
    container.querySelector('#save-interval').value = currentSaveIntervalSeconds;
    startAutoSave();
  }

  // ページ離脱時の緊急バックアップ
  window.addEventListener('beforeunload', () => {
    const unsyncedData = localData.filter(item => !item.synced);
    if (unsyncedData.length > 0) {
      localStorage.setItem('emergencyBackup', JSON.stringify(unsyncedData));
    }
  });
}

function(container, apiUrl, tables) {
  let currentRecords = [];
  let deleteTargetId = null;

  // 時間フォーマット関数
  function formatTime(timestamp) {
    if (!timestamp) return '-';
    const date = new Date(timestamp);
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  // 日付フォーマット関数
  function formatDate(timestamp) {
    if (!timestamp) return '-';
    const date = new Date(timestamp);
    return date.toLocaleDateString('ja-JP');
  }

  // 作業時間計算関数（分単位）
  function calculateWorkTime(startTime, endTime, breakTime = 0) {
    if (!startTime || !endTime) return 0;
    const start = new Date(startTime);
    const end = new Date(endTime);
    const totalMinutes = Math.floor((end - start) / (1000 * 60));
    return Math.max(0, totalMinutes - breakTime);
  }

  // 時間表示フォーマット（分 → 時間分）
  function formatDuration(minutes) {
    if (!minutes || minutes === 0) return '0分';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    if (hours === 0) return `${mins}分`;
    if (mins === 0) return `${hours}時間`;
    return `${hours}時間${mins}分`;
  }

  // 異常値チェック関数
  function checkAnomalies(record, breakTime = 0) {
    const warnings = [];

    if (record.作業開始時刻 && record.作業終了時刻) {
      const workMinutes = calculateWorkTime(record.作業開始時刻, record.作業終了時刻, breakTime);

      // 24時間を超える作業時間
      if (workMinutes > 1440) {
        warnings.push('24時間を超える作業時間');
      }

      // 終了時刻が開始時刻より早い
      if (new Date(record.作業終了時刻) < new Date(record.作業開始時刻)) {
        warnings.push('終了時刻が開始時刻より早い');
      }
    }

    // 中断時間が作業時間を超える
    if (breakTime > 0 && record.作業開始時刻 && record.作業終了時刻) {
      const totalMinutes = Math.floor((new Date(record.作業終了時刻) - new Date(record.作業開始時刻)) / (1000 * 60));
      if (breakTime > totalMinutes) {
        warnings.push('中断時間が実働時間を超える');
      }
    }

    return warnings;
  }

  // 中断時間取得関数
  async function getBreakTime(recordId) {
    try {
      const breakRecords = await window.aivicApi.list(2); // 中断記録テーブル
      if (!breakRecords) return 0;

      const recordBreaks = breakRecords.filter(br => br.作業記録ID === recordId);
      return recordBreaks.reduce((total, br) => total + (br.中断時間 || 0), 0);
    } catch (error) {
      console.error('中断時間取得エラー:', error);
      return 0;
    }
  }

  // テーブル再描画関数
  async function renderRows(rows) {
    const tbody = container.querySelector('#records-tbody');
    const emptyState = container.querySelector('#empty-state');

    if (!rows || rows.length === 0) {
      tbody.innerHTML = '';
      emptyState.style.display = 'block';
      return;
    }

    emptyState.style.display = 'none';

    // 各レコードの中断時間を取得して表示
    const rowsWithBreaks = await Promise.all(rows.map(async (record) => {
      const breakTime = await getBreakTime(record.作業記録ID);
      const workTime = calculateWorkTime(record.作業開始時刻, record.作業終了時刻, breakTime);
      const warnings = checkAnomalies(record, breakTime);

      return {
        ...record,
        breakTime,
        workTime,
        warnings
      };
    }));

    tbody.innerHTML = rowsWithBreaks.map(record => {
      const warningIcon = record.warnings.length > 0 
        ? `<span style="color: #ff6a00; margin-left: 4px; cursor: help;" title="${record.warnings.join(', ')}">⚠️</span>`
        : '';

      const canEdit = record.承認状態 !== '承認済み';
      const canDelete = record.承認状態 !== '承認済み';
      const canApprove = record.承認状態 === '未承認';

      return `
        <tr data-id="${record.作業記録ID}">
          <td>${formatDate(record.作業日)}${warningIcon}</td>
          <td>${record.プロジェクト名 || '-'}</td>
          <td>${formatTime(record.作業開始時刻)}</td>
          <td>${formatTime(record.作業終了時刻)}</td>
          <td>${formatDuration(record.workTime)}</td>
          <td>${formatDuration(record.breakTime)}</td>
          <td>${record.作業場所 || '-'}</td>
          <td>${record.進捗状況 || '-'}</td>
          <td>
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; 
              ${record.承認状態 === '承認済み' ? 'background: rgba(0,255,0,0.1); color: #00aa00;' : 
                record.承認状態 === '差し戻し' ? 'background: rgba(255,0,0,0.1); color: #aa0000;' : 
                'background: rgba(255,165,0,0.1); color: #ff8800;'}">
              ${record.承認状態 || '未承認'}
            </span>
          </td>
          <td>
            <div style="display: flex; gap: 4px;">
              <button class="action-btn secondary detail-btn" data-id="${record.作業記録ID}" data-testid="detail-button" style="font-size: 11px; padding: 4px 8px;">詳細</button>
              ${canEdit ? `<button class="action-btn secondary edit-btn" data-id="${record.作業記録ID}" data-testid="edit-button" style="font-size: 11px; padding: 4px 8px;">修正</button>` : ''}
              ${canDelete ? `<button class="action-btn secondary delete-btn" data-id="${record.作業記録ID}" data-testid="delete-button" style="font-size: 11px; padding: 4px 8px;">削除</button>` : ''}
              ${canApprove ? `<button class="action-btn approve-btn" data-id="${record.作業記録ID}" data-testid="approve-button" style="font-size: 11px; padding: 4px 8px;">承認</button>` : ''}
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 詳細表示関数
  async function showDetail(recordId) {
    const record = currentRecords.find(r => r.作業記録ID === recordId);
    if (!record) return;

    const breakTime = await getBreakTime(recordId);
    const workTime = calculateWorkTime(record.作業開始時刻, record.作業終了時刻, breakTime);

    const detailContent = container.querySelector('#detail-content');
    detailContent.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px; font-size: 13px;">
        <div><strong>作業日:</strong> ${formatDate(record.作業日)}</div>
        <div><strong>プロジェクト名:</strong> ${record.プロジェクト名 || '-'}</div>
        <div><strong>開始時刻:</strong> ${formatTime(record.作業開始時刻)}</div>
        <div><strong>終了時刻:</strong> ${formatTime(record.作業終了時刻)}</div>
        <div><strong>作業時間:</strong> ${formatDuration(workTime)}</div>
        <div><strong>中断時間:</strong> ${formatDuration(breakTime)}</div>
        <div><strong>作業場所:</strong> ${record.作業場所 || '-'}</div>
        <div><strong>作業種別:</strong> ${record.作業種別 || '-'}</div>
        <div style="grid-column: 1 / -1;"><strong>作業内容:</strong><br>${record.作業内容 || '-'}</div>
        <div style="grid-column: 1 / -1;"><strong>備考:</strong><br>${record.備考 || '-'}</div>
        <div><strong>進捗状況:</strong> ${record.進捗状況 || '-'}</div>
        <div><strong>承認状態:</strong> ${record.承認状態 || '未承認'}</div>
      </div>
    `;

    container.querySelector('#detail-modal').style.display = 'block';
  }

  // CSVエクスポート関数
  async function exportCSV() {
    try {
      const allRecords = await window.aivicApi.list(1);
      if (!allRecords || allRecords.length === 0) {
        showError('エクスポートするデータがありません');
        return;
      }

      const headers = ['日付', '作業項目', '開始時刻', '終了時刻', '作業時間', '作業場所', '作業種別', '作業内容', '進捗状況', '承認状態', '備考'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...allRecords.map(record => [
          formatDate(record.作業日),
          record.プロジェクト名 || '',
          formatTime(record.作業開始時刻),
          formatTime(record.作業終了時刻),
          formatDuration(record.作業時間 || 0),
          record.作業場所 || '',
          record.作業種別 || '',
          `"${(record.作業内容 || '').replace(/"/g, '""')}"`,
          record.進捗状況 || '',
          record.承認状態 || '',
          `"${(record.備考 || '').replace(/"/g, '""')}"`
        ].join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `作業記録_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      console.error('CSVエクスポートエラー:', error);
      showError('CSVエクスポートに失敗しました');
    }
  }

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // 日付バリデーション関数
  function validateDateRange(startDate, endDate) {
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      showError('開始日は終了日より前の日付を指定してください');
      return false;
    }
    return true;
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      const records = await window.aivicApi.list(1);
      currentRecords = records || [];
      await renderRows(currentRecords);
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      currentRecords = tables[1]?.records || [];
      await renderRows(currentRecords);
    }
  }

  // 絞り込み処理
  async function filterRecords() {
    const dateFilter = container.querySelector('#date-filter').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;

    if (!validateDateRange(startDate, endDate)) {
      return;
    }

    try {
      const allRecords = await window.aivicApi.list(1);
      if (!allRecords) {
        await renderRows([]);
        return;
      }

      let filteredRecords = allRecords;

      // 単一日付フィルター
      if (dateFilter) {
        const filterDate = new Date(dateFilter).toDateString();
        filteredRecords = filteredRecords.filter(record => {
          if (!record.作業日) return false;
          return new Date(record.作業日).toDateString() === filterDate;
        });
      }

      // 期間フィルター
      if (startDate || endDate) {
        filteredRecords = filteredRecords.filter(record => {
          if (!record.作業日) return false;
          const recordDate = new Date(record.作業日);

          if (startDate && recordDate < new Date(startDate)) return false;
          if (endDate && recordDate > new Date(endDate)) return false;

          return true;
        });
      }

      currentRecords = filteredRecords;
      await renderRows(filteredRecords);
    } catch (error) {
      console.error('絞り込みエラー:', error);
      showError('絞り込み処理でエラーが発生しました');
    }
  }

  // イベントリスナー設定
  container.querySelector('#btn-back-menu').addEventListener('click', () => {
    window.showScreen('scr-1778907133295');
  });

  container.querySelector('#btn-filter').addEventListener('click', filterRecords);

  container.querySelector('#btn-export-csv').addEventListener('click', exportCSV);

  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#detail-modal').style.display = 'none';
  });

  container.querySelector('#btn-cancel-delete').addEventListener('click', () => {
    container.querySelector('#delete-modal').style.display = 'none';
    deleteTargetId = null;
  });

  container.querySelector('#btn-confirm-delete').addEventListener('click', async () => {
    if (!deleteTargetId) return;

    try {
      await window.aivicApi.delete(1, deleteTargetId);
      container.querySelector('#delete-modal').style.display = 'none';
      deleteTargetId = null;
      await loadData();
    } catch (error) {
      console.error('削除エラー:', error);
      showError('削除に失敗しました');
    }
  });

  // イベントデリゲーション
  container.addEventListener('click', async (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    const editBtn = e.target.closest('.edit-btn');
    const deleteBtn = e.target.closest('.delete-btn');
    const approveBtn = e.target.closest('.approve-btn');

    if (detailBtn) {
      await showDetail(detailBtn.dataset.id);
    }

    if (editBtn) {
      // 編集権限チェック
      const record = currentRecords.find(r => r.作業記録ID === editBtn.dataset.id);
      if (record && record.承認状態 === '承認済み') {
        showError('承認済みの記録は修正できません');
        return;
      }
      window.showScreen('scr-1778907343735');
    }

    if (deleteBtn) {
      // 削除権限チェック
      const record = currentRecords.find(r => r.作業記録ID === deleteBtn.dataset.id);
      if (record && record.承認状態 === '承認済み') {
        showError('承認済みの記録は削除できません');
        return;
      }
      deleteTargetId = deleteBtn.dataset.id;
      container.querySelector('#delete-modal').style.display = 'block';
    }

    if (approveBtn) {
      try {
        await window.aivicApi.update(1, approveBtn.dataset.id, { 承認状態: '承認済み', 承認日時: new Date().toISOString() });
        await loadData();
      } catch (error) {
        console.error('承認エラー:', error);
        showError('承認処理でエラーが発生しました');
      }
    }
  });

  // 初期データ読み込み
  loadData();

  // 今日の日付を初期値として設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#date-filter').value = today;
}

function(container, apiUrl, tables) {
  let mediaRecorder = null;
  let audioChunks = [];
  let isRecording = false;
  let selectedPhoto = null;
  let recordedAudio = null;

  // 現在時刻を中断開始時刻にセット
  const now = new Date();
  const startTimeInput = container.querySelector('#start-time');
  startTimeInput.value = now.toISOString().slice(0, 16);

  // 作業項目マスタの読み込み
  async function loadWorkItems() {
    const workItemSelect = container.querySelector('#work-item');
    try {
      const workItems = await window.aivicApi.list(3); // 作業項目マスタ
      if (workItems) {
        workItems.forEach(item => {
          const option = document.createElement('option');
          option.value = item.作業項目ID;
          option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
          workItemSelect.appendChild(option);
        });
      }
    } catch (error) {
      console.error('作業項目の読み込みに失敗しました:', error);
    }
  }

  // 中断時間の自動計算
  function updateDuration() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const durationDisplay = container.querySelector('#duration-display');

    if (startTime && endTime) {
      const start = new Date(startTime);
      const end = new Date(endTime);
      const diffMs = end - start;

      if (diffMs > 0) {
        const hours = Math.floor(diffMs / (1000 * 60 * 60));
        const minutes = Math.floor((diffMs % (1000 * 60 * 60)) / (1000 * 60));
        durationDisplay.textContent = `${hours}時間${minutes}分`;
      } else {
        durationDisplay.textContent = '終了時刻が開始時刻より前です';
      }
    } else {
      durationDisplay.textContent = '自動計算されます';
    }
  }

  // 文字数カウント
  function updateCharCount() {
    const details = container.querySelector('#details');
    const charCount = container.querySelector('#char-count');
    charCount.textContent = `(${details.value.length}/1000)`;
  }

  // 影響範囲の全選択・全解除
  function handleSelectAllImpact() {
    const selectAll = container.querySelector('#select-all-impact');
    const impactCheckboxes = container.querySelectorAll('input[name="impact"]');

    selectAll.addEventListener('change', () => {
      impactCheckboxes.forEach(cb => {
        cb.checked = selectAll.checked;
      });
    });

    impactCheckboxes.forEach(cb => {
      cb.addEventListener('change', () => {
        const allChecked = Array.from(impactCheckboxes).every(checkbox => checkbox.checked);
        const noneChecked = Array.from(impactCheckboxes).every(checkbox => !checkbox.checked);
        selectAll.checked = allChecked;
        selectAll.indeterminate = !allChecked && !noneChecked;
      });
    });
  }

  // 写真アップロード処理
  function handlePhotoUpload() {
    const photoBtn = container.querySelector('#photo-btn');
    const photoUpload = container.querySelector('#photo-upload');
    const photoPreview = container.querySelector('#photo-preview');
    const previewImg = container.querySelector('#preview-img');
    const removePhoto = container.querySelector('#remove-photo');

    photoBtn.addEventListener('click', () => {
      photoUpload.click();
    });

    photoUpload.addEventListener('change', (e) => {
      const file = e.target.files[0];
      if (file) {
        // ファイルサイズチェック (10MB)
        if (file.size > 10 * 1024 * 1024) {
          showError('ファイルサイズが10MBを超えています');
          return;
        }

        // ファイル形式チェック
        if (!file.type.startsWith('image/')) {
          showError('画像ファイルのみアップロード可能です');
          return;
        }

        selectedPhoto = file;
        const reader = new FileReader();
        reader.onload = (e) => {
          previewImg.src = e.target.result;
          photoPreview.style.display = 'block';
        };
        reader.readAsDataURL(file);
      }
    });

    removePhoto.addEventListener('click', () => {
      selectedPhoto = null;
      photoPreview.style.display = 'none';
      photoUpload.value = '';
    });
  }

  // 音声録音処理
  function handleVoiceRecording() {
    const voiceBtn = container.querySelector('#voice-btn');
    const voicePreview = container.querySelector('#voice-preview');
    const previewAudio = container.querySelector('#preview-audio');
    const removeVoice = container.querySelector('#remove-voice');

    voiceBtn.addEventListener('click', async () => {
      if (!isRecording) {
        try {
          const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
          mediaRecorder = new MediaRecorder(stream);
          audioChunks = [];

          mediaRecorder.ondataavailable = (event) => {
            audioChunks.push(event.data);
          };

          mediaRecorder.onstop = () => {
            const audioBlob = new Blob(audioChunks, { type: 'audio/wav' });
            recordedAudio = audioBlob;
            const audioUrl = URL.createObjectURL(audioBlob);
            previewAudio.src = audioUrl;
            voicePreview.style.display = 'block';
            stream.getTracks().forEach(track => track.stop());
          };

          mediaRecorder.start();
          isRecording = true;
          voiceBtn.textContent = '🛑 録音停止';
        } catch (error) {
          showError('マイクへのアクセスが拒否されました');
        }
      } else {
        mediaRecorder.stop();
        isRecording = false;
        voiceBtn.textContent = '🎤 録音開始';
      }
    });

    removeVoice.addEventListener('click', () => {
      recordedAudio = null;
      voicePreview.style.display = 'none';
      if (previewAudio.src) {
        URL.revokeObjectURL(previewAudio.src);
      }
    });
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    const startTime = container.querySelector('#start-time').value;
    const reason = container.querySelector('#reason').value;
    const endTime = container.querySelector('#end-time').value;
    const details = container.querySelector('#details').value;

    if (!startTime) {
      showError('中断開始時刻は必須です');
      return false;
    }

    if (!reason) {
      showError('中断理由は必須です');
      return false;
    }

    // 未来時刻チェック
    const now = new Date();
    const startDateTime = new Date(startTime);
    if (startDateTime > now) {
      showError('未来の時刻は入力できません');
      return false;
    }

    if (endTime) {
      const endDateTime = new Date(endTime);
      if (endDateTime > now) {
        showError('未来の時刻は入力できません');
        return false;
      }
      if (endDateTime <= startDateTime) {
        showError('終了時刻は開始時刻より後に設定してください');
        return false;
      }
    }

    // 文字数チェック
    if (details.length > 1000) {
      showError('中断詳細は1000文字以内で入力してください');
      return false;
    }

    return true;
  }

  // フォームデータ収集
  function collectFormData() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const reason = container.querySelector('#reason').value;
    const location = container.querySelector('#location').value;
    const details = container.querySelector('#details').value;
    const workItem = container.querySelector('#work-item').value;
    const urgency = container.querySelector('input[name="urgency"]:checked')?.value || '';

    const impactCheckboxes = container.querySelectorAll('input[name="impact"]:checked');
    const impact = Array.from(impactCheckboxes).map(cb => cb.value).join(', ');

    // 中断時間計算
    let duration = null;
    if (startTime && endTime) {
      const start = new Date(startTime);
      const end = new Date(endTime);
      duration = Math.floor((end - start) / (1000 * 60)); // 分単位
    }

    return {
      中断記録ID: crypto.randomUUID(),
      作業記録ID: workItem || null,
      中断開始日時: startTime,
      中断終了日時: endTime || null,
      中断理由区分: reason,
      中断理由詳細: details,
      中断時間: duration,
      影響度: urgency,
      対応状況: '対応中',
      記録者ID: 'current-user-id', // 実際の実装では認証情報から取得
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };
  }

  // 一時保存
  async function tempSave() {
    const formData = collectFormData();
    localStorage.setItem('interruption_temp_data', JSON.stringify(formData));

    // 成功メッセージ表示
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = '一時保存しました';
    errorDiv.style.background = 'rgba(34, 197, 94, 0.1)';
    errorDiv.style.borderColor = 'rgba(34, 197, 94, 0.3)';
    errorDiv.style.color = '#86efac';
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
      errorDiv.style.background = 'rgba(220, 38, 38, 0.1)';
      errorDiv.style.borderColor = 'rgba(220, 38, 38, 0.3)';
      errorDiv.style.color = '#fca5a5';
    }, 3000);
  }

  // 記録完了
  async function completeRecord() {
    if (!validateForm()) return;

    const formData = collectFormData();

    try {
      const saved = await window.aivicApi.save(2, formData); // 中断記録テーブル
      if (saved) {
        // 一時保存データを削除
        localStorage.removeItem('interruption_temp_data');

        // 作業再開記録画面に遷移
        window.showScreen("scr-1778907251446");
      } else {
        showError('記録の保存に失敗しました');
      }
    } catch (error) {
      showError('ネットワークエラーが発生しました');
    }
  }

  // 一時保存データの復元
  function restoreTempData() {
    const tempData = localStorage.getItem('interruption_temp_data');
    if (tempData) {
      try {
        const data = JSON.parse(tempData);
        if (data.中断開始日時) container.querySelector('#start-time').value = data.中断開始日時.slice(0, 16);
        if (data.中断終了日時) container.querySelector('#end-time').value = data.中断終了日時.slice(0, 16);
        if (data.中断理由区分) container.querySelector('#reason').value = data.中断理由区分;
        if (data.中断理由詳細) container.querySelector('#details').value = data.中断理由詳細;
        if (data.作業記録ID) container.querySelector('#work-item').value = data.作業記録ID;

        updateCharCount();
        updateDuration();
      } catch (error) {
        console.error('一時保存データの復元に失敗しました:', error);
      }
    }
  }

  // イベントリスナー設定
  container.querySelector('#start-time').addEventListener('change', updateDuration);
  container.querySelector('#end-time').addEventListener('change', updateDuration);
  container.querySelector('#details').addEventListener('input', updateCharCount);
  container.querySelector('#btn-temp-save').addEventListener('click', tempSave);
  container.querySelector('#btn-complete').addEventListener('click', completeRecord);

  // 初期化
  loadWorkItems();
  handleSelectAllImpact();
  handlePhotoUpload();
  handleVoiceRecording();
  restoreTempData();
  updateCharCount();
}

function(container, apiUrl, tables) {
  let selectedWorkRecord = null;
  let selectedSuspendRecord = null;

  // 現在時刻を設定
  function setCurrentTime() {
    const now = new Date();
    const localDateTime = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
    container.querySelector("#resume-time").value = localDateTime;
  }

  // 中断中作業一覧を描画
  function renderSuspendedWorks(workRecords, suspendRecords) {
    const tbody = container.querySelector("#suspended-works-tbody");
    const noWorksDiv = container.querySelector("#no-suspended-works");

    // 中断中の作業記録を抽出（進捗状況が「中断」のもの）
    const suspendedWorks = workRecords.filter(work => work.進捗状況 === "中断");

    if (suspendedWorks.length === 0) {
      tbody.innerHTML = "";
      noWorksDiv.classList.remove("hidden");
      return;
    }

    noWorksDiv.classList.add("hidden");

    tbody.innerHTML = suspendedWorks.map(work => {
      // 対応する中断記録を検索
      const suspendRecord = suspendRecords.find(s => s.作業記録ID === work.作業記録ID && !s.中断終了日時);
      const suspendTime = suspendRecord ? new Date(suspendRecord.中断開始日時).toLocaleString() : "-";
      const suspendReason = suspendRecord ? suspendRecord.中断理由詳細 || suspendRecord.中断理由区分 : "-";

      return `
        <tr data-work-id="${work.作業記録ID}" data-suspend-id="${suspendRecord?.中断記録ID || ''}" style="cursor: pointer;">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${work.作業内容 || work.プロジェクト名}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${suspendTime}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${suspendReason}</td>
          <td style="padding: 6px 10px;">
            <button class="select-work-btn action-btn" data-work-id="${work.作業記録ID}" data-suspend-id="${suspendRecord?.中断記録ID || ''}"
                    style="background: var(--primary); color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 12px; cursor: pointer;">
              選択
            </button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 選択された作業の詳細を表示
  function showSelectedWork(workRecord, suspendRecord) {
    selectedWorkRecord = workRecord;
    selectedSuspendRecord = suspendRecord;

    container.querySelector("#selected-work-name").textContent = workRecord.作業内容 || workRecord.プロジェクト名;
    container.querySelector("#selected-suspend-time").textContent = suspendRecord ? 
      new Date(suspendRecord.中断開始日時).toLocaleString() : "-";

    container.querySelector("#selected-work-area").classList.remove("hidden");
    container.querySelector("#resume-form-area").classList.remove("hidden");

    setCurrentTime();
  }

  // 文字数カウント更新
  function updateCharCount() {
    const textarea = container.querySelector("#resume-reason-detail");
    const charCount = container.querySelector("#char-count");
    charCount.textContent = textarea.value.length;
  }

  // バリデーション
  function validateForm() {
    const reasonDetail = container.querySelector("#resume-reason-detail").value.trim();
    const errorDiv = container.querySelector("#reason-error");

    if (!reasonDetail) {
      errorDiv.textContent = "再開理由は必須入力です";
      errorDiv.classList.remove("hidden");
      return false;
    }

    if (reasonDetail.length > 500) {
      errorDiv.textContent = "再開理由は500文字以内で入力してください";
      errorDiv.classList.remove("hidden");
      return false;
    }

    errorDiv.classList.add("hidden");
    return true;
  }

  // 作業再開処理
  async function resumeWork() {
    if (!validateForm()) return;

    const resumeTime = container.querySelector("#resume-time").value;
    const reasonSelect = container.querySelector("#resume-reason-select").value;
    const reasonDetail = container.querySelector("#resume-reason-detail").value.trim();

    try {
      // 作業記録を「作業中」に更新
      const updatedWork = await window.aivicApi.update(1, selectedWorkRecord.作業記録ID, {
        進捗状況: "作業中",
        更新日時: new Date().toISOString()
      });

      if (!updatedWork) {
        alert("作業記録の更新に失敗しました");
        return;
      }

      // 中断記録を終了
      if (selectedSuspendRecord) {
        await window.aivicApi.update(2, selectedSuspendRecord.中断記録ID, {
          中断終了日時: resumeTime,
          対応状況: "解決済み",
          更新日時: new Date().toISOString()
        });
      }

      // 新しい中断記録として再開理由を記録（再開記録として）
      await window.aivicApi.save(2, {
        作業記録ID: selectedWorkRecord.作業記録ID,
        中断開始日時: resumeTime,
        中断理由区分: reasonSelect || "その他",
        中断理由詳細: reasonDetail,
        中断時間: 0,
        対応状況: "解決済み",
        記録者ID: selectedWorkRecord.作業員ID,
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString()
      });

      alert("作業を再開しました");
      window.showScreen("scr-1778907296658"); // 工数入力画面へ遷移

    } catch (error) {
      console.error("作業再開エラー:", error);
      alert("作業再開に失敗しました");
    }
  }

  // 初期データ読み込みと描画
  async function loadData() {
    try {
      const workRecords = await window.aivicApi.list(1) || tables[1]?.records || [];
      const suspendRecords = await window.aivicApi.list(2) || tables[2]?.records || [];
      renderSuspendedWorks(workRecords, suspendRecords);
    } catch (error) {
      console.error("データ読み込みエラー:", error);
      renderSuspendedWorks(tables[1]?.records || [], tables[2]?.records || []);
    }
  }

  // イベントリスナー設定

  // 作業選択
  container.addEventListener("click", async (e) => {
    const selectBtn = e.target.closest(".select-work-btn");
    if (selectBtn) {
      const workId = selectBtn.dataset.workId;
      const suspendId = selectBtn.dataset.suspendId;

      try {
        const workRecords = await window.aivicApi.list(1) || tables[1]?.records || [];
        const suspendRecords = await window.aivicApi.list(2) || tables[2]?.records || [];

        const workRecord = workRecords.find(w => w.作業記録ID === workId);
        const suspendRecord = suspendRecords.find(s => s.中断記録ID === suspendId);

        if (workRecord) {
          showSelectedWork(workRecord, suspendRecord);
        }
      } catch (error) {
        console.error("作業選択エラー:", error);
      }
    }
  });

  // 再開理由選択変更時
  container.querySelector("#resume-reason-select").addEventListener("change", (e) => {
    const textarea = container.querySelector("#resume-reason-detail");
    if (e.target.value && e.target.value !== "その他") {
      textarea.value = e.target.value;
      updateCharCount();
    }
  });

  // 文字数カウント
  container.querySelector("#resume-reason-detail").addEventListener("input", updateCharCount);

  // 作業再開ボタン
  container.querySelector("#btn-resume").addEventListener("click", () => {
    if (!selectedWorkRecord) {
      alert("作業を選択してください");
      return;
    }

    // 確認ダイアログを表示
    container.querySelector("#resume-confirm-dialog").classList.remove("hidden");
  });

  // ダイアログのOKボタン
  container.querySelector("#dialog-ok").addEventListener("click", () => {
    container.querySelector("#resume-confirm-dialog").classList.add("hidden");
    resumeWork();
  });

  // ダイアログのキャンセルボタン
  container.querySelector("#dialog-cancel").addEventListener("click", () => {
    container.querySelector("#resume-confirm-dialog").classList.add("hidden");
  });

  // キャンセルボタン
  container.querySelector("#btn-cancel").addEventListener("click", () => {
    container.querySelector("#selected-work-area").classList.add("hidden");
    container.querySelector("#resume-form-area").classList.add("hidden");
    container.querySelector("#resume-reason-select").value = "";
    container.querySelector("#resume-reason-detail").value = "";
    container.querySelector("#reason-error").classList.add("hidden");
    updateCharCount();
    selectedWorkRecord = null;
    selectedSuspendRecord = null;
  });

  // 戻るボタン
  container.querySelector("#btn-back").addEventListener("click", () => {
    window.history.back();
  });

  // 初期化
  loadData();
  updateCharCount();
}

function(container, apiUrl, tables) {
  // エラー情報の初期化
  let errorInfo = {
    title: "システムエラーが発生しました",
    message: "申し訳ございませんが、システムで問題が発生しました。しばらく時間をおいてから再度お試しください。",
    code: "E001",
    timestamp: new Date().toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    }).replace(/\//g, '/'),
    type: "システムエラー",
    location: "データ保存処理",
    cause: "ネットワーク接続の問題またはサーバーの一時的な障害",
    recommendation: "しばらく時間をおいてから再試行してください"
  };

  // URLパラメータからエラー情報を取得
  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.get('error')) {
    try {
      const errorData = JSON.parse(decodeURIComponent(urlParams.get('error')));
      errorInfo = { ...errorInfo, ...errorData };
    } catch (e) {
      console.warn('エラー情報の解析に失敗しました:', e);
    }
  }

  // エラー情報を画面に反映
  function updateErrorDisplay() {
    container.querySelector('#error-message').textContent = errorInfo.message;
    container.querySelector('#error-code').textContent = `エラーコード: ${errorInfo.code}`;
    container.querySelector('#error-timestamp').textContent = `発生時刻: ${errorInfo.timestamp}`;
    container.querySelector('#error-type').textContent = errorInfo.type;
    container.querySelector('#error-location').textContent = errorInfo.location;
    container.querySelector('#error-cause').textContent = errorInfo.cause;
    container.querySelector('#error-recommendation').textContent = errorInfo.recommendation;

    // 長いエラーメッセージの制限
    const messageElement = container.querySelector('#error-message');
    if (errorInfo.message.length > 500) {
      messageElement.textContent = errorInfo.message.substring(0, 500) + '...';
    }
  }

  updateErrorDisplay();

  // 再試行ボタンの処理
  let isRetrying = false;
  container.querySelector('#btn-retry').addEventListener('click', async function() {
    if (isRetrying) return;

    isRetrying = true;
    const button = this;
    const originalText = button.textContent;
    button.textContent = '再試行中...';
    button.disabled = true;

    try {
      // ネットワーク接続チェック
      if (!navigator.onLine) {
        throw new Error('ネットワーク接続がありません');
      }

      // 前の画面に戻るか、元の操作を再実行
      const previousScreen = sessionStorage.getItem('previousScreen');
      if (previousScreen) {
        window.showScreen(previousScreen);
      } else {
        // デフォルトで工数記録画面に戻る
        window.showScreen('scr-1778907133295');
      }
    } catch (error) {
      // 再試行失敗
      errorInfo.message = '再試行に失敗しました。ネットワーク接続を確認してください。';
      errorInfo.code = 'E002';
      errorInfo.timestamp = new Date().toLocaleString('ja-JP', {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
      }).replace(/\//g, '/');
      updateErrorDisplay();
    } finally {
      isRetrying = false;
      button.textContent = originalText;
      button.disabled = false;
    }
  });

  // 戻るボタンの処理
  container.querySelector('#btn-back').addEventListener('click', function() {
    // セッション切れチェック
    const sessionValid = sessionStorage.getItem('userSession');
    if (!sessionValid) {
      window.location.href = './login.html';
      return;
    }

    const previousScreen = sessionStorage.getItem('previousScreen');
    if (previousScreen) {
      window.showScreen(previousScreen);
    } else {
      // 履歴がない場合は工数記録画面に戻る
      window.showScreen('scr-1778907133295');
    }
  });

  // ホームに戻るボタンの処理
  container.querySelector('#btn-home').addEventListener('click', function() {
    // セッション切れチェック
    const sessionValid = sessionStorage.getItem('userSession');
    if (!sessionValid) {
      window.location.href = './login.html';
      return;
    }

    // 工数記録画面（ホーム画面）に遷移
    window.showScreen('scr-1778907133295');
  });

  // エラー詳細表示ボタンの処理
  container.querySelector('#btn-show-details').addEventListener('click', async function() {
    const detailsElement = container.querySelector('#error-details');
    const button = this;

    if (detailsElement.classList.contains('hidden')) {
      try {
        // エラー詳細情報の取得を試行
        if (!navigator.onLine) {
          throw new Error('ネットワーク接続がありません');
        }

        detailsElement.classList.remove('hidden');
        button.textContent = 'エラー詳細を隠す';
      } catch (error) {
        // エラー詳細情報が取得できない場合
        const detailsContent = container.querySelector('#error-details-content');
        detailsContent.innerHTML = '<div style="color: var(--text-muted);">エラーの詳細情報を取得できませんでした。ネットワーク接続を確認してください。</div>';
        detailsElement.classList.remove('hidden');
        button.textContent = 'エラー詳細を隠す';
      }
    } else {
      detailsElement.classList.add('hidden');
      button.textContent = 'エラー詳細表示';
    }
  });

  // 管理者に連絡ボタンの処理
  container.querySelector('#btn-contact-admin').addEventListener('click', async function() {
    try {
      // ネットワーク接続チェック
      if (!navigator.onLine) {
        throw new Error('ネットワーク接続がありません');
      }

      // 管理者連絡機能が利用可能かチェック
      const response = await fetch(`${apiUrl}/api/contact/status`).catch(() => {
        throw new Error('管理者連絡機能が利用できません');
      });

      if (!response.ok) {
        throw new Error('管理者連絡機能が利用できません');
      }

      // 緊急報告画面に遷移
      window.showScreen('scr-1778907330826');
    } catch (error) {
      // 管理者連絡機能が利用できない場合の代替手段を表示
      const contactInfo = container.querySelector('#contact-info');
      contactInfo.classList.remove('hidden');

      // エラーメッセージを更新
      const messageElement = container.querySelector('#error-message');
      messageElement.textContent = '管理者連絡機能が現在利用できません。下記の連絡先まで直接お問い合わせください。';
    }
  });

  // 現在の画面を前の画面として記録
  sessionStorage.setItem('previousScreen', 'scr-1778907133295');

  // ページ読み込み時にネットワーク状態をチェック
  if (!navigator.onLine) {
    errorInfo.message = 'ネットワーク接続がありません。接続を確認してから再試行してください。';
    errorInfo.code = 'E003';
    errorInfo.cause = 'ネットワーク接続の問題';
    updateErrorDisplay();
  }

  // ネットワーク状態の変化を監視
  window.addEventListener('online', function() {
    console.log('ネットワーク接続が復旧しました');
  });

  window.addEventListener('offline', function() {
    errorInfo.message = 'ネットワーク接続が切断されました。接続を確認してから再試行してください。';
    errorInfo.code = 'E003';
    errorInfo.timestamp = new Date().toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    }).replace(/\//g, '/');
    updateErrorDisplay();
  });
}

function(container, apiUrl, tables) {
  let interruptions = [];

  // 現在のユーザー情報を設定
  const currentUser = { id: 'user-001', name: '田中太郎' };
  container.querySelector('#worker-name').value = currentUser.name;

  // 作業項目マスタを読み込み
  function loadWorkItems() {
    const workItemSelect = container.querySelector('#work-item');
    const workItemsTable = tables.find(t => t.tableName === '作業項目マスタ');
    if (workItemsTable && workItemsTable.records) {
      workItemsTable.records.forEach(item => {
        if (item.有効フラグ) {
          const option = document.createElement('option');
          option.value = item.作業項目ID;
          option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
          workItemSelect.appendChild(option);
        }
      });
    }
  }

  // 実働時間を計算
  function calculateActualHours() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;

    if (!startTime || !endTime) {
      container.querySelector('#actual-hours').value = '';
      return;
    }

    const start = new Date(`2000-01-01T${startTime}`);
    const end = new Date(`2000-01-01T${endTime}`);

    // 24時間をまたぐ場合の処理
    if (end < start) {
      end.setDate(end.getDate() + 1);
    }

    const diffMs = end - start;
    const diffMinutes = Math.floor(diffMs / (1000 * 60));
    const actualMinutes = diffMinutes - breakTime;

    if (actualMinutes < 0) {
      container.querySelector('#actual-hours').value = '';
      return;
    }

    const hours = Math.floor(actualMinutes / 60);
    const minutes = actualMinutes % 60;
    container.querySelector('#actual-hours').value = `${hours}時間${minutes.toString().padStart(2, '0')}分`;
  }

  // 文字数カウント
  function updateCharCount() {
    const textarea = container.querySelector('#work-details');
    const charCount = container.querySelector('#char-count');
    charCount.textContent = textarea.value.length;
  }

  // 中断記録の表示
  function renderInterruptions() {
    const tbody = container.querySelector('#interruption-tbody');
    tbody.innerHTML = interruptions.map((item, index) => {
      const duration = item.endTime ? calculateInterruptionDuration(item.startTime, item.endTime) : '未終了';
      return `
        <tr>
          <td style="padding: 6px 10px; color: var(--text);">${item.reason}</td>
          <td style="padding: 6px 10px; color: var(--text);">${item.startTime}</td>
          <td style="padding: 6px 10px; color: var(--text);">${item.endTime || '-'}</td>
          <td style="padding: 6px 10px; color: var(--text);">${duration}</td>
          <td style="padding: 6px 10px; text-align: center;">
            <button class="action-btn secondary delete-interruption" data-index="${index}" style="padding: 4px 8px; font-size: 12px;">削除</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 中断時間の計算
  function calculateInterruptionDuration(startTime, endTime) {
    const start = new Date(`2000-01-01T${startTime}`);
    const end = new Date(`2000-01-01T${endTime}`);

    if (end < start) {
      end.setDate(end.getDate() + 1);
    }

    const diffMs = end - start;
    const diffMinutes = Math.floor(diffMs / (1000 * 60));
    const hours = Math.floor(diffMinutes / 60);
    const minutes = diffMinutes % 60;

    return `${hours}時間${minutes.toString().padStart(2, '0')}分`;
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    const workDate = container.querySelector('#work-date').value;
    const workItem = container.querySelector('#work-item').value;
    const workLocation = container.querySelector('#work-location').value;
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;
    const workDetails = container.querySelector('#work-details').value;

    // 必須項目チェック
    if (!workDate) {
      showError('作業日付を入力してください');
      return false;
    }

    if (!workItem) {
      showError('作業項目を選択してください');
      return false;
    }

    if (!workLocation) {
      showError('作業場所を入力してください');
      return false;
    }

    if (!startTime) {
      showError('開始時刻を入力してください');
      return false;
    }

    if (!endTime) {
      showError('終了時刻を入力してください');
      return false;
    }

    if (!workDetails.trim()) {
      showError('作業内容詳細を入力してください');
      return false;
    }

    // 未来日付チェック
    const today = new Date();
    const selectedDate = new Date(workDate);
    if (selectedDate > today) {
      showError('未来の日付は選択できません');
      return false;
    }

    // 時刻フォーマットチェック
    const timeRegex = /^([01]?[0-9]|2[0-3]):[0-5][0-9]$/;
    if (!timeRegex.test(startTime)) {
      showError('開始時刻の形式が正しくありません');
      return false;
    }

    if (!timeRegex.test(endTime)) {
      showError('終了時刻の形式が正しくありません');
      return false;
    }

    // 開始終了時刻の関係チェック
    if (startTime === endTime) {
      showError('開始時刻と終了時刻が同じです');
      return false;
    }

    // 実働時間の計算と検証
    const start = new Date(`2000-01-01T${startTime}`);
    const end = new Date(`2000-01-01T${endTime}`);
    if (end < start) {
      end.setDate(end.getDate() + 1);
    }

    const diffMs = end - start;
    const diffMinutes = Math.floor(diffMs / (1000 * 60));
    const actualMinutes = diffMinutes - breakTime;

    if (actualMinutes <= 0) {
      showError('休憩時間が実働時間を超過しています');
      return false;
    }

    // 文字数制限チェック
    if (workDetails.length > 1000) {
      showError('作業内容詳細は1000文字以内で入力してください');
      return false;
    }

    return true;
  }

  // 初期設定
  loadWorkItems();

  // 今日の日付を設定
  const today = new Date();
  container.querySelector('#work-date').value = today.toISOString().split('T')[0];

  // イベントリスナー設定
  container.querySelector('#start-time').addEventListener('change', calculateActualHours);
  container.querySelector('#end-time').addEventListener('change', calculateActualHours);
  container.querySelector('#break-time').addEventListener('input', calculateActualHours);
  container.querySelector('#work-details').addEventListener('input', updateCharCount);

  // 進捗状況変更時の中断セクション表示制御
  container.querySelector('#progress-status').addEventListener('change', function() {
    const interruptionSection = container.querySelector('#interruption-section');
    if (this.value === '中断') {
      interruptionSection.style.display = 'block';
    } else {
      interruptionSection.style.display = 'none';
    }
  });

  // 中断記録追加
  container.querySelector('#add-interruption').addEventListener('click', function() {
    const reason = container.querySelector('#interruption-reason').value;
    const startTime = container.querySelector('#interruption-start').value;
    const endTime = container.querySelector('#interruption-end').value;

    if (!reason) {
      showError('中断理由を選択してください');
      return;
    }

    if (!startTime) {
      showError('中断開始時刻を入力してください');
      return;
    }

    if (!endTime) {
      showError('中断終了時刻を入力してください');
      return;
    }

    if (startTime >= endTime) {
      showError('中断開始時刻は終了時刻より前に設定してください');
      return;
    }

    interruptions.push({
      reason: reason,
      startTime: startTime,
      endTime: endTime
    });

    renderInterruptions();

    // フォームクリア
    container.querySelector('#interruption-reason').value = '';
    container.querySelector('#interruption-start').value = '';
    container.querySelector('#interruption-end').value = '';
  });

  // 中断記録削除
  container.addEventListener('click', function(e) {
    if (e.target.classList.contains('delete-interruption')) {
      const index = parseInt(e.target.dataset.index);
      interruptions.splice(index, 1);
      renderInterruptions();
    }
  });

  // 作業中断ボタン
  container.querySelector('#btn-interrupt').addEventListener('click', function() {
    window.showScreen("scr-1778907238439");
  });

  // 登録ボタン
  container.querySelector('#btn-save').addEventListener('click', async function() {
    if (!validateForm()) return;

    const workData = {
      作業員ID: currentUser.id,
      作業日: new Date(container.querySelector('#work-date').value).toISOString(),
      作業開始時刻: new Date(`${container.querySelector('#work-date').value}T${container.querySelector('#start-time').value}`).toISOString(),
      作業終了時刻: new Date(`${container.querySelector('#work-date').value}T${container.querySelector('#end-time').value}`).toISOString(),
      作業時間: calculateWorkMinutes(),
      プロジェクト名: getSelectedWorkItemName(),
      作業場所: container.querySelector('#work-location').value,
      作業種別: getSelectedWorkItemName(),
      作業内容: container.querySelector('#work-details').value,
      進捗状況: container.querySelector('#progress-status').value,
      備考: '',
      承認状態: '未承認',
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: currentUser.id
    };

    const saved = await window.aivicApi.save(1, workData);
    if (saved) {
      // 中断記録も保存
      for (const interruption of interruptions) {
        const interruptionData = {
          作業記録ID: saved.作業記録ID,
          中断開始日時: new Date(`${container.querySelector('#work-date').value}T${interruption.startTime}`).toISOString(),
          中断終了日時: new Date(`${container.querySelector('#work-date').value}T${interruption.endTime}`).toISOString(),
          中断理由区分: interruption.reason,
          中断理由詳細: '',
          中断時間: calculateInterruptionMinutes(interruption.startTime, interruption.endTime),
          影響度: '軽微',
          対応状況: '解決済み',
          記録者ID: currentUser.id,
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString()
        };
        await window.aivicApi.save(2, interruptionData);
      }

      alert('工数記録が正常に登録されました');

      // フォームリセット
      container.querySelector('#work-entry-form').reset();
      container.querySelector('#worker-name').value = currentUser.name;
      container.querySelector('#work-date').value = today.toISOString().split('T')[0];
      container.querySelector('#actual-hours').value = '';
      interruptions = [];
      renderInterruptions();
      container.querySelector('#interruption-section').style.display = 'none';
      updateCharCount();
    }
  });

  // 作業終了ボタン
  container.querySelector('#btn-complete').addEventListener('click', function() {
    window.showScreen("scr-1778907199709");
  });

  // ヘルパー関数
  function calculateWorkMinutes() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;

    const start = new Date(`2000-01-01T${startTime}`);
    const end = new Date(`2000-01-01T${endTime}`);

    if (end < start) {
      end.setDate(end.getDate() + 1);
    }

    const diffMs = end - start;
    const diffMinutes = Math.floor(diffMs / (1000 * 60));
    return diffMinutes - breakTime;
  }

  function calculateInterruptionMinutes(startTime, endTime) {
    const start = new Date(`2000-01-01T${startTime}`);
    const end = new Date(`2000-01-01T${endTime}`);

    if (end < start) {
      end.setDate(end.getDate() + 1);
    }

    const diffMs = end - start;
    return Math.floor(diffMs / (1000 * 60));
  }

  function getSelectedWorkItemName() {
    const select = container.querySelector('#work-item');
    const selectedOption = select.options[select.selectedIndex];
    return selectedOption ? selectedOption.textContent : '';
  }
}

function(container, apiUrl, tables) {
  let workRecords = [];
  let workItems = [];
  let currentRecord = null;

  // 初期データ読み込み
  async function loadData() {
    try {
      workRecords = await window.aivicApi.list(1) || tables[1]?.records || [];
      workItems = await window.aivicApi.list(3) || tables[3]?.records || [];

      // 修正対象記録ドロップダウンを更新
      const targetSelect = container.querySelector("#target-record");
      targetSelect.innerHTML = '<option value="">選択してください</option>' + 
        workRecords.map(record => 
          `<option value="${record.id}">${record.作業日 || ''} - ${record.作業内容 || ''} (${record.作業員ID || ''})</option>`
        ).join('');

      // 作業項目ドロップダウンを更新
      const workItemSelect = container.querySelector("#work-item");
      workItemSelect.innerHTML = '<option value="">選択してください</option>' + 
        workItems.filter(item => item.有効フラグ).map(item => 
          `<option value="${item.id}">${item.作業項目名}</option>`
        ).join('');
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 時間計算関数
  function calculateTimes() {
    const startTime = container.querySelector("#start-time").value;
    const endTime = container.querySelector("#end-time").value;
    const breakTime = container.querySelector("#break-time").value;

    if (!startTime || !endTime) {
      container.querySelector("#actual-work-time").textContent = '-';
      container.querySelector("#break-duration").textContent = '-';
      return;
    }

    const start = new Date(`2000-01-01T${startTime}`);
    const end = new Date(`2000-01-01T${endTime}`);

    if (end <= start) {
      container.querySelector("#actual-work-time").textContent = '-';
      container.querySelector("#break-duration").textContent = '-';
      return;
    }

    const totalMinutes = (end - start) / (1000 * 60);
    let breakMinutes = 0;

    if (breakTime && currentRecord) {
      // 中断時間を計算（簡易版：30分固定）
      breakMinutes = 30;
      container.querySelector("#break-duration").textContent = `${breakMinutes}分`;
    } else {
      container.querySelector("#break-duration").textContent = '-';
    }

    const actualMinutes = totalMinutes - breakMinutes;
    const hours = Math.floor(actualMinutes / 60);
    const minutes = actualMinutes % 60;

    container.querySelector("#actual-work-time").textContent = 
      `${hours}時間${minutes}分`;
  }

  // バリデーション関数
  function validateForm() {
    const errors = [];
    const warnings = [];

    const targetRecord = container.querySelector("#target-record").value;
    const workDate = container.querySelector("#work-date").value;
    const startTime = container.querySelector("#start-time").value;
    const endTime = container.querySelector("#end-time").value;
    const correctionReason = container.querySelector("#correction-reason").value.trim();

    // 必須項目チェック
    if (!targetRecord) {
      errors.push('修正対象記録を選択してください');
    }

    if (!correctionReason) {
      errors.push('修正理由を入力してください');
    }

    // 日付チェック
    if (workDate) {
      const date = new Date(workDate);
      const today = new Date();
      const minDate = new Date('1900-01-01');
      const maxDate = new Date('2099-12-31');

      if (date < minDate || date > maxDate) {
        errors.push('作業日付は1900年1月1日から2099年12月31日の間で入力してください');
      }

      if (date > today) {
        warnings.push('未来の日付が入力されています');
      }
    }

    // 時刻チェック
    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);

      if (end <= start) {
        errors.push('開始時刻は終了時刻より前の時刻を入力してください');
      }

      const totalHours = (end - start) / (1000 * 60 * 60);
      if (totalHours > 16) {
        warnings.push('16時間を超える長時間作業が入力されています');
      }
    }

    // 中断時刻チェック
    const breakTime = container.querySelector("#break-time").value;
    if (breakTime && startTime && endTime) {
      const breakDateTime = new Date(`2000-01-01T${breakTime}`);
      const startDateTime = new Date(`2000-01-01T${startTime}`);
      const endDateTime = new Date(`2000-01-01T${endTime}`);

      if (breakDateTime < startDateTime || breakDateTime > endDateTime) {
        errors.push('中断時刻は作業時間内で入力してください');
      }
    }

    return { errors, warnings };
  }

  // エラー・警告表示
  function showValidationMessages(errors, warnings) {
    const errorArea = container.querySelector("#error-area");
    const warningArea = container.querySelector("#warning-area");

    if (errors.length > 0) {
      container.querySelector("#error-messages").innerHTML = 
        errors.map(msg => `<div>• ${msg}</div>`).join('');
      errorArea.style.display = 'block';
    } else {
      errorArea.style.display = 'none';
    }

    if (warnings.length > 0) {
      container.querySelector("#warning-messages").innerHTML = 
        warnings.map(msg => `<div>• ${msg}</div>`).join('');
      warningArea.style.display = 'block';
    } else {
      warningArea.style.display = 'none';
    }
  }

  // 修正対象記録選択時の処理
  container.querySelector("#target-record").addEventListener("change", function() {
    const recordId = this.value;
    if (!recordId) {
      currentRecord = null;
      container.querySelector("#original-data").textContent = "修正対象記録を選択してください";
      // フォームをクリア
      container.querySelector("#work-date").value = "";
      container.querySelector("#start-time").value = "";
      container.querySelector("#end-time").value = "";
      container.querySelector("#work-item").value = "";
      container.querySelector("#break-time").value = "";
      container.querySelector("#break-reason").value = "";
      container.querySelector("#correction-reason").value = "";
      calculateTimes();
      return;
    }

    currentRecord = workRecords.find(r => r.id === recordId);
    if (currentRecord) {
      // 修正前データを表示
      const originalData = `
        <div><strong>作業日:</strong> ${currentRecord.作業日 || '-'}</div>
        <div><strong>作業時間:</strong> ${currentRecord.作業開始時刻 || '-'} ～ ${currentRecord.作業終了時刻 || '-'}</div>
        <div><strong>作業内容:</strong> ${currentRecord.作業内容 || '-'}</div>
        <div><strong>プロジェクト:</strong> ${currentRecord.プロジェクト名 || '-'}</div>
        <div><strong>作業場所:</strong> ${currentRecord.作業場所 || '-'}</div>
        <div><strong>進捗状況:</strong> ${currentRecord.進捗状況 || '-'}</div>
      `;
      container.querySelector("#original-data").innerHTML = originalData;

      // フォームに現在の値を設定
      if (currentRecord.作業日) {
        container.querySelector("#work-date").value = currentRecord.作業日.split('T')[0];
      }
      if (currentRecord.作業開始時刻) {
        const startTime = new Date(currentRecord.作業開始時刻);
        container.querySelector("#start-time").value = 
          `${startTime.getHours().toString().padStart(2, '0')}:${startTime.getMinutes().toString().padStart(2, '0')}`;
      }
      if (currentRecord.作業終了時刻) {
        const endTime = new Date(currentRecord.作業終了時刻);
        container.querySelector("#end-time").value = 
          `${endTime.getHours().toString().padStart(2, '0')}:${endTime.getMinutes().toString().padStart(2, '0')}`;
      }

      calculateTimes();
    }
  });

  // 時刻変更時の自動計算
  container.querySelector("#start-time").addEventListener("change", calculateTimes);
  container.querySelector("#end-time").addEventListener("change", calculateTimes);
  container.querySelector("#break-time").addEventListener("change", calculateTimes);

  // 文字数カウント
  container.querySelector("#correction-reason").addEventListener("input", function() {
    const count = this.value.length;
    container.querySelector("#char-count").textContent = count;

    if (count > 200) {
      this.value = this.value.substring(0, 200);
      container.querySelector("#char-count").textContent = 200;
    }
  });

  // 保存ボタン
  container.querySelector("#btn-save").addEventListener("click", async function() {
    const { errors, warnings } = validateForm();
    showValidationMessages(errors, warnings);

    if (errors.length > 0) {
      return;
    }

    if (!currentRecord) {
      showValidationMessages(['修正対象記録を選択してください'], []);
      return;
    }

    try {
      const workDate = container.querySelector("#work-date").value;
      const startTime = container.querySelector("#start-time").value;
      const endTime = container.querySelector("#end-time").value;
      const workItem = container.querySelector("#work-item").value;
      const breakTime = container.querySelector("#break-time").value;
      const breakReason = container.querySelector("#break-reason").value;
      const correctionReason = container.querySelector("#correction-reason").value.trim();

      // 作業記録を更新
      const updateData = {
        ...currentRecord,
        作業日: workDate ? new Date(workDate).toISOString() : currentRecord.作業日,
        作業開始時刻: startTime ? new Date(`${workDate || currentRecord.作業日.split('T')[0]}T${startTime}`).toISOString() : currentRecord.作業開始時刻,
        作業終了時刻: endTime ? new Date(`${workDate || currentRecord.作業日.split('T')[0]}T${endTime}`).toISOString() : currentRecord.作業終了時刻,
        備考: `${currentRecord.備考 || ''}\n[修正] ${correctionReason}`.trim(),
        更新日時: new Date().toISOString()
      };

      const updated = await window.aivicApi.update(1, currentRecord.id, updateData);

      if (updated) {
        // 中断記録がある場合は更新
        if (breakTime && breakReason) {
          const breakRecords = await window.aivicApi.list(2) || [];
          const existingBreak = breakRecords.find(b => b.作業記録ID === currentRecord.id);

          if (existingBreak) {
            await window.aivicApi.update(2, existingBreak.id, {
              ...existingBreak,
              中断開始日時: new Date(`${workDate || currentRecord.作業日.split('T')[0]}T${breakTime}`).toISOString(),
              中断理由区分: breakReason,
              更新日時: new Date().toISOString()
            });
          } else {
            await window.aivicApi.save(2, {
              作業記録ID: currentRecord.id,
              中断開始日時: new Date(`${workDate || currentRecord.作業日.split('T')[0]}T${breakTime}`).toISOString(),
              中断理由区分: breakReason,
              中断理由詳細: correctionReason,
              対応状況: '対応中',
              記録者ID: currentRecord.作業員ID,
              作成日時: new Date().toISOString(),
              更新日時: new Date().toISOString()
            });
          }
        }

        alert('修正が完了しました');
        window.showScreen('scr-1778907145716'); // 作業履歴一覧画面へ
      }
    } catch (error) {
      console.error('保存エラー:', error);
      showValidationMessages(['保存中にエラーが発生しました'], []);
    }
  });

  // キャンセルボタン
  container.querySelector("#btn-cancel").addEventListener("click", function() {
    if (confirm('修正内容が失われますが、よろしいですか？')) {
      window.showScreen('scr-1778907145716'); // 作業履歴一覧画面へ
    }
  });

  // 初期化
  loadData();
}

function(container, apiUrl, tables) {
  let selectedFiles = [];
  let currentDraftId = null;

  // 現在のユーザー情報を取得して報告者名に設定
  const currentUser = JSON.parse(localStorage.getItem('currentUser') || '{}');
  const reporterNameInput = container.querySelector('#reporter-name');
  if (currentUser.氏名) {
    reporterNameInput.value = currentUser.氏名;
  }

  // 作業項目マスタを読み込み
  async function loadWorkItems() {
    const workItemSelect = container.querySelector('#work-item');
    try {
      const workItems = await window.aivicApi.list(3); // 作業項目マスタのテーブルインデックス
      if (workItems) {
        workItems.forEach(item => {
          if (item.有効フラグ) {
            const option = document.createElement('option');
            option.value = item.作業項目ID;
            option.textContent = item.作業項目名;
            workItemSelect.appendChild(option);
          }
        });
      }
    } catch (error) {
      console.error('作業項目の読み込みに失敗しました:', error);
    }
  }

  // 発生日時のデフォルト値を現在時刻に設定
  const occurrenceDatetime = container.querySelector('#occurrence-datetime');
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  occurrenceDatetime.value = now.toISOString().slice(0, 16);

  // 文字数カウンター
  const emergencyContent = container.querySelector('#emergency-content');
  const contentCounter = container.querySelector('#content-counter');

  emergencyContent.addEventListener('input', function() {
    const length = this.value.length;
    contentCounter.textContent = `(${length}/1000)`;
    if (length > 1000) {
      contentCounter.style.color = '#ff4444';
    } else {
      contentCounter.style.color = 'var(--text-muted)';
    }
  });

  // 写真添付機能
  const photoInput = container.querySelector('#photo-input');
  const photoButton = container.querySelector('#photo-button');
  const photoCount = container.querySelector('#photo-count');
  const photoPreview = container.querySelector('#photo-preview');
  const photoError = container.querySelector('#photo-error');

  photoButton.addEventListener('click', () => {
    photoInput.click();
  });

  photoInput.addEventListener('change', function(e) {
    const files = Array.from(e.target.files);

    // ファイル数チェック
    if (selectedFiles.length + files.length > 5) {
      showError('photo-error', '写真は最大5枚まで添付できます');
      return;
    }

    files.forEach(file => {
      // ファイル形式チェック
      if (!file.type.startsWith('image/')) {
        showError('photo-error', 'サポートされていないファイル形式です。画像ファイルを選択してください');
        return;
      }

      // ファイルサイズチェック (5MB)
      if (file.size > 5 * 1024 * 1024) {
        showError('photo-error', 'ファイルサイズは5MB以下にしてください');
        return;
      }

      selectedFiles.push(file);

      // プレビュー表示
      const reader = new FileReader();
      reader.onload = function(e) {
        const previewItem = document.createElement('div');
        previewItem.style.cssText = 'position: relative; border-radius: 4px; overflow: hidden;';
        previewItem.innerHTML = `
          <img src="${e.target.result}" style="width: 80px; height: 80px; object-fit: cover; display: block;">
          <button type="button" class="remove-photo" data-index="${selectedFiles.length - 1}" style="position: absolute; top: 2px; right: 2px; width: 20px; height: 20px; background: rgba(0,0,0,0.7); color: #fff; border: none; border-radius: 50%; font-size: 12px; cursor: pointer; display: flex; align-items: center; justify-content: center;">×</button>
        `;
        photoPreview.appendChild(previewItem);
      };
      reader.readAsDataURL(file);
    });

    updatePhotoCount();
    hideError('photo-error');
  });

  // 写真削除
  photoPreview.addEventListener('click', function(e) {
    if (e.target.classList.contains('remove-photo')) {
      const index = parseInt(e.target.dataset.index);
      selectedFiles.splice(index, 1);
      e.target.closest('div').remove();
      updatePhotoCount();

      // インデックスを再設定
      const removeButtons = photoPreview.querySelectorAll('.remove-photo');
      removeButtons.forEach((btn, i) => {
        btn.dataset.index = i;
      });
    }
  });

  function updatePhotoCount() {
    photoCount.textContent = `${selectedFiles.length}枚選択中 (最大5枚)`;
  }

  // バリデーション関数
  function validateForm() {
    let isValid = true;

    // 緊急度チェック
    const urgency = container.querySelector('input[name="urgency"]:checked');
    if (!urgency) {
      showError('urgency-error', '緊急度を選択してください');
      isValid = false;
    } else {
      hideError('urgency-error');
    }

    // 報告種別チェック
    const reportType = container.querySelector('#report-type').value;
    if (!reportType) {
      showError('report-type-error', '報告種別を選択してください');
      isValid = false;
    } else {
      hideError('report-type-error');
    }

    // 発生日時チェック
    const occurrenceDateTime = container.querySelector('#occurrence-datetime').value;
    if (!occurrenceDateTime) {
      showError('occurrence-datetime-error', '発生日時を入力してください');
      isValid = false;
    } else {
      const selectedDate = new Date(occurrenceDateTime);
      const now = new Date();
      if (selectedDate > now) {
        showError('occurrence-datetime-error', '発生日時に未来の日付は入力できません');
        isValid = false;
      } else {
        hideError('occurrence-datetime');
      }
    }

    // 発生場所チェック
    const location = container.querySelector('#occurrence-location').value.trim();
    if (!location) {
      showError('occurrence-location-error', '発生場所を入力してください');
      isValid = false;
    } else {
      hideError('occurrence-location-error');
    }

    // 緊急事態内容チェック
    const content = container.querySelector('#emergency-content').value.trim();
    if (!content) {
      showError('emergency-content-error', '緊急事態内容を入力してください');
      isValid = false;
    } else if (content.length > 1000) {
      showError('emergency-content-error', '緊急事態内容は1000文字以内で入力してください');
      isValid = false;
    } else {
      hideError('emergency-content-error');
    }

    // 連絡先電話番号チェック
    const phone = container.querySelector('#contact-phone').value.trim();
    if (!phone) {
      showError('contact-phone-error', '連絡先電話番号を入力してください');
      isValid = false;
    } else {
      const phonePattern = /^(\d{2,4}-\d{2,4}-\d{4}|\d{10,11})$/;
      if (!phonePattern.test(phone)) {
        showError('contact-phone-error', '正しい電話番号の形式で入力してください');
        isValid = false;
      } else {
        hideError('contact-phone-error');
      }
    }

    return isValid;
  }

  function showError(elementId, message) {
    const errorElement = container.querySelector(`#${elementId}`);
    if (errorElement) {
      errorElement.textContent = message;
      errorElement.style.display = 'block';
    }
  }

  function hideError(elementId) {
    const errorElement = container.querySelector(`#${elementId}`);
    if (errorElement) {
      errorElement.style.display = 'none';
    }
  }

  // フォームデータ収集
  function collectFormData() {
    const urgency = container.querySelector('input[name="urgency"]:checked');
    return {
      緊急度: urgency ? urgency.value : '',
      報告種別: container.querySelector('#report-type').value,
      発生日時: container.querySelector('#occurrence-datetime').value,
      発生場所: container.querySelector('#occurrence-location').value.trim(),
      作業項目ID: container.querySelector('#work-item').value,
      緊急事態内容: container.querySelector('#emergency-content').value.trim(),
      報告者名: container.querySelector('#reporter-name').value,
      連絡先電話番号: container.querySelector('#contact-phone').value.trim(),
      添付写真数: selectedFiles.length,
      報告日時: new Date().toISOString(),
      報告者ID: currentUser.ユーザーID || null,
      状態: '報告済み'
    };
  }

  // 下書き保存
  container.querySelector('#draft-save-btn').addEventListener('click', async function() {
    const formData = collectFormData();
    formData.状態 = '下書き';

    try {
      let result;
      if (currentDraftId) {
        result = await window.aivicApi.update(4, currentDraftId, formData); // 異常値検出ログテーブルを緊急報告用に使用
      } else {
        result = await window.aivicApi.save(4, formData);
        if (result) {
          currentDraftId = result.id;
        }
      }

      if (result) {
        showSuccessMessage('下書きを保存しました');
      }
    } catch (error) {
      console.error('下書き保存エラー:', error);
      showError('photo-error', '下書きの保存に失敗しました');
    }
  });

  // 緊急報告送信
  container.querySelector('#submit-btn').addEventListener('click', async function() {
    if (!validateForm()) {
      return;
    }

    const formData = collectFormData();

    try {
      const result = await window.aivicApi.save(4, formData); // 異常値検出ログテーブルを緊急報告用に使用

      if (result) {
        showSuccessMessage('緊急報告を送信しました。関係者に通知されます。');

        // フォームを無効化
        const form = container.querySelector('#emergency-form');
        const inputs = form.querySelectorAll('input, select, textarea');
        inputs.forEach(input => input.disabled = true);

        // ボタンを切り替え
        container.querySelector('#submit-btn').style.display = 'none';
        container.querySelector('#draft-save-btn').style.display = 'none';
        container.querySelector('#complete-btn').style.display = 'inline-block';
      }
    } catch (error) {
      console.error('緊急報告送信エラー:', error);
      showError('photo-error', '緊急報告の送信に失敗しました');
    }
  });

  // 報告完了ボタン
  container.querySelector('#complete-btn').addEventListener('click', function() {
    window.showScreen("scr-1778907133295"); // 工数記録画面
  });

  function showSuccessMessage(message) {
    const successElement = container.querySelector('#success-message');
    successElement.textContent = message;
    successElement.style.display = 'block';

    setTimeout(() => {
      successElement.style.display = 'none';
    }, 5000);
  }

  // 初期化処理
  loadWorkItems();

  // 下書きデータの復元（ページ読み込み時）
  async function loadDraft() {
    try {
      const drafts = await window.aivicApi.list(4);
      if (drafts) {
        const userDraft = drafts.find(d => d.状態 === '下書き' && d.報告者ID === currentUser.ユーザーID);
        if (userDraft) {
          currentDraftId = userDraft.id;

          // フォームに値を復元
          if (userDraft.緊急度) {
            const urgencyRadio = container.querySelector(`input[name="urgency"][value="${userDraft.緊急度}"]`);
            if (urgencyRadio) urgencyRadio.checked = true;
          }
          if (userDraft.報告種別) {
            container.querySelector('#report-type').value = userDraft.報告種別;
          }
          if (userDraft.発生日時) {
            container.querySelector('#occurrence-datetime').value = userDraft.発生日時;
          }
          if (userDraft.発生場所) {
            container.querySelector('#occurrence-location').value = userDraft.発生場所;
          }
          if (userDraft.作業項目ID) {
            container.querySelector('#work-item').value = userDraft.作業項目ID;
          }
          if (userDraft.緊急事態内容) {
            container.querySelector('#emergency-content').value = userDraft.緊急事態内容;
            emergencyContent.dispatchEvent(new Event('input')); // 文字数カウンター更新
          }
          if (userDraft.連絡先電話番号) {
            container.querySelector('#contact-phone').value = userDraft.連絡先電話番号;
          }
        }
      }
    } catch (error) {
      console.error('下書きデータの読み込みエラー:', error);
    }
  }

  loadDraft();
}

function(container, apiUrl, tables) {
  let selectedRecordId = null;
  let originalData = null;
  let workItems = [];

  // 作業項目マスタを読み込み
  async function loadWorkItems() {
    const items = await window.aivicApi.list(3); // 作業項目マスタ
    if (items) {
      workItems = items.filter(item => item.有効フラグ);
      const select = container.querySelector('#work-item-select');
      select.innerHTML = '<option value="">選択してください</option>';
      workItems.forEach(item => {
        select.innerHTML += `<option value="${item.作業項目ID}">${item.作業項目名}</option>`;
      });
    }
  }

  // 作業記録一覧を読み込み
  async function loadWorkRecords() {
    const records = await window.aivicApi.list(1); // 作業記録
    if (records) {
      const select = container.querySelector('#work-record-select');
      select.innerHTML = '<option value="">選択してください</option>';
      records.forEach(record => {
        const date = new Date(record.作業日).toLocaleDateString('ja-JP');
        const content = record.作業内容.length > 20 ? record.作業内容.substring(0, 20) + '...' : record.作業内容;
        select.innerHTML += `<option value="${record.作業記録ID}">${date} - ${content}</option>`;
      });
    }
  }

  // 時間計算
  function calculateTime() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      let end = new Date(`2000-01-01T${endTime}`);

      // 24時間跨ぎの場合
      if (end < start) {
        end.setDate(end.getDate() + 1);
      }

      const diffMs = end - start;
      const totalMinutes = Math.floor(diffMs / (1000 * 60));
      const netMinutes = Math.max(0, totalMinutes - breakTime);

      const totalHours = Math.floor(totalMinutes / 60);
      const totalMins = totalMinutes % 60;
      const netHours = Math.floor(netMinutes / 60);
      const netMins = netMinutes % 60;

      container.querySelector('#total-work-time').value = `${totalHours}時間${totalMins}分`;
      container.querySelector('#net-work-time').value = `${netHours}時間${netMins}分`;
    } else {
      container.querySelector('#total-work-time').value = '';
      container.querySelector('#net-work-time').value = '';
    }
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    container.querySelector('#warning-message').style.display = 'none';
  }

  // 警告表示
  function showWarning(message) {
    const warningDiv = container.querySelector('#warning-message');
    warningDiv.textContent = message;
    warningDiv.style.display = 'block';
    container.querySelector('#error-message').style.display = 'none';
  }

  // エラー・警告非表示
  function hideMessages() {
    container.querySelector('#error-message').style.display = 'none';
    container.querySelector('#warning-message').style.display = 'none';
  }

  // バリデーション
  function validateForm() {
    hideMessages();

    const recordId = container.querySelector('#work-record-select').value;
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;
    const reason = container.querySelector('#correction-reason').value.trim();

    if (!recordId) {
      showError('修正対象の作業記録を選択してください');
      return false;
    }

    if (!startTime || !endTime) {
      showError('作業開始時刻と終了時刻を入力してください');
      return false;
    }

    const start = new Date(`2000-01-01T${startTime}`);
    let end = new Date(`2000-01-01T${endTime}`);

    if (end < start) {
      end.setDate(end.getDate() + 1);
    }

    if (start.getTime() === end.getTime()) {
      showError('作業時間が0分です。開始時刻と終了時刻を確認してください。');
      return false;
    }

    const totalMinutes = Math.floor((end - start) / (1000 * 60));

    if (breakTime > totalMinutes) {
      showError('中断時間が作業時間を超過しています');
      return false;
    }

    if (!reason) {
      showError('修正理由を入力してください');
      return false;
    }

    if (reason.length > 500) {
      showError('修正理由は500文字以内で入力してください');
      return false;
    }

    const workContent = container.querySelector('#work-content').value;
    if (workContent.length > 1000) {
      showError('作業内容詳細は1000文字以内で入力してください');
      return false;
    }

    // 異常値チェック
    if (totalMinutes > 24 * 60) {
      showWarning('作業時間が24時間を超えています。内容を確認してください。');
    } else if (totalMinutes > 12 * 60) {
      showWarning('作業時間が12時間を超えています。内容を確認してください。');
    }

    return true;
  }

  // 作業記録選択時の処理
  container.querySelector('#work-record-select').addEventListener('change', async function() {
    const recordId = this.value;
    if (!recordId) {
      selectedRecordId = null;
      originalData = null;
      // フォームクリア
      container.querySelector('#work-date-display').value = '';
      container.querySelector('#start-time').value = '';
      container.querySelector('#end-time').value = '';
      container.querySelector('#break-time').value = '';
      container.querySelector('#work-item-select').value = '';
      container.querySelector('#work-content').value = '';
      container.querySelector('#correction-reason').value = '';
      calculateTime();
      return;
    }

    const records = await window.aivicApi.list(1);
    const record = records?.find(r => r.作業記録ID === recordId);
    if (record) {
      selectedRecordId = recordId;
      originalData = { ...record };

      // フォームに値を設定
      const workDate = new Date(record.作業日);
      container.querySelector('#work-date-display').value = workDate.toLocaleDateString('ja-JP');

      const startTime = new Date(record.作業開始時刻);
      const endTime = record.作業終了時刻 ? new Date(record.作業終了時刻) : null;

      container.querySelector('#start-time').value = startTime.toTimeString().substring(0, 5);
      if (endTime) {
        container.querySelector('#end-time').value = endTime.toTimeString().substring(0, 5);
      }

      // 中断時間を計算（中断記録から）
      const breakRecords = await window.aivicApi.list(2);
      const totalBreakTime = breakRecords?.filter(br => br.作業記録ID === recordId)
        .reduce((sum, br) => sum + (br.中断時間 || 0), 0) || 0;
      container.querySelector('#break-time').value = totalBreakTime;

      container.querySelector('#work-content').value = record.作業内容 || '';

      calculateTime();
    }
  });

  // 時間入力時の計算
  container.querySelector('#start-time').addEventListener('change', calculateTime);
  container.querySelector('#end-time').addEventListener('change', calculateTime);
  container.querySelector('#break-time').addEventListener('input', calculateTime);

  // 元データ参照ボタン
  container.querySelector('#btn-view-original').addEventListener('click', function() {
    if (!originalData) {
      showError('修正対象の作業記録を選択してください');
      return;
    }

    const modal = container.querySelector('#original-data-modal');
    const content = container.querySelector('#original-data-content');

    const startTime = new Date(originalData.作業開始時刻);
    const endTime = originalData.作業終了時刻 ? new Date(originalData.作業終了時刻) : null;
    const workDate = new Date(originalData.作業日);

    content.innerHTML = `
      <div style="margin-bottom: 8px;"><strong>作業日:</strong> ${workDate.toLocaleDateString('ja-JP')}</div>
      <div style="margin-bottom: 8px;"><strong>開始時刻:</strong> ${startTime.toTimeString().substring(0, 5)}</div>
      <div style="margin-bottom: 8px;"><strong>終了時刻:</strong> ${endTime ? endTime.toTimeString().substring(0, 5) : '未設定'}</div>
      <div style="margin-bottom: 8px;"><strong>プロジェクト名:</strong> ${originalData.プロジェクト名 || ''}</div>
      <div style="margin-bottom: 8px;"><strong>作業場所:</strong> ${originalData.作業場所 || ''}</div>
      <div style="margin-bottom: 8px;"><strong>作業種別:</strong> ${originalData.作業種別 || ''}</div>
      <div style="margin-bottom: 8px;"><strong>作業内容:</strong> ${originalData.作業内容 || ''}</div>
      <div style="margin-bottom: 8px;"><strong>進捗状況:</strong> ${originalData.進捗状況 || ''}</div>
      <div style="margin-bottom: 8px;"><strong>備考:</strong> ${originalData.備考 || ''}</div>
    `;

    modal.style.display = 'block';
  });

  // モーダル閉じる
  container.querySelector('#btn-close-modal').addEventListener('click', function() {
    container.querySelector('#original-data-modal').style.display = 'none';
  });

  // 保存ボタン
  container.querySelector('#btn-save').addEventListener('click', async function() {
    if (!validateForm()) return;

    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;
    const workItemId = container.querySelector('#work-item-select').value;
    const workContent = container.querySelector('#work-content').value;
    const reason = container.querySelector('#correction-reason').value;

    // 作業記録を更新
    const startDateTime = new Date(originalData.作業日);
    const [startHour, startMin] = startTime.split(':');
    startDateTime.setHours(parseInt(startHour), parseInt(startMin), 0, 0);

    const endDateTime = new Date(originalData.作業日);
    const [endHour, endMin] = endTime.split(':');
    endDateTime.setHours(parseInt(endHour), parseInt(endMin), 0, 0);

    // 24時間跨ぎの場合
    if (endDateTime < startDateTime) {
      endDateTime.setDate(endDateTime.getDate() + 1);
    }

    const totalMinutes = Math.floor((endDateTime - startDateTime) / (1000 * 60));

    const updateData = {
      作業開始時刻: startDateTime.toISOString(),
      作業終了時刻: endDateTime.toISOString(),
      作業時間: totalMinutes,
      作業内容: workContent,
      更新日時: new Date().toISOString()
    };

    const updated = await window.aivicApi.update(1, selectedRecordId, updateData);
    if (updated) {
      // 異常値検出ログに記録
      if (totalMinutes > 12 * 60) {
        await window.aivicApi.save(4, {
          異常値検出ログID: crypto.randomUUID(),
          検出対象テーブル: '作業記録',
          検出対象レコードID: selectedRecordId,
          ユーザーID: originalData.作業員ID,
          異常値種別: '長時間作業',
          検出項目: '作業時間',
          検出値: `${totalMinutes}分`,
          閾値: '720分',
          重要度: totalMinutes > 24 * 60 ? '高' : '中',
          確認状況: '未確認',
          通知送信フラグ: false,
          検出日時: new Date().toISOString(),
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString()
