function(container, apiUrl, tables) {
  let workRecords = [];
  let users = [];
  let workItems = [];
  let interruptions = [];
  let anomalies = [];

  // DOM要素の取得
  const startDateInput = container.querySelector('#start-date');
  const endDateInput = container.querySelector('#end-date');
  const outputFormatSelect = container.querySelector('#output-format');
  const workerSelect = container.querySelector('#worker-select');
  const workItemSelect = container.querySelector('#work-item-select');
  const workLocationSelect = container.querySelector('#work-location');
  const includeAnomalyCheckbox = container.querySelector('#include-anomaly');
  const includeInterruptionCheckbox = container.querySelector('#include-interruption');
  const conditionPreview = container.querySelector('#condition-preview');
  const dataCount = container.querySelector('#data-count');
  const errorMessage = container.querySelector('#error-message');
  const previewSection = container.querySelector('#preview-section');
  const previewTbody = container.querySelector('#preview-tbody');
  const processingOverlay = container.querySelector('#processing-overlay');
  const progressBar = container.querySelector('#progress-bar');

  // 初期データの読み込み
  async function loadInitialData() {
    try {
      // 作業記録データ（tableIndex: 1）
      const workRecordsData = await window.aivicApi.list(1);
      if (workRecordsData) workRecords = workRecordsData;

      // ユーザーデータ（tableIndex: 0）
      const usersData = await window.aivicApi.list(0);
      if (usersData) users = usersData;

      // 作業項目マスタ（tableIndex: 3）
      const workItemsData = await window.aivicApi.list(3);
      if (workItemsData) workItems = workItemsData;

      // 中断記録（tableIndex: 2）
      const interruptionsData = await window.aivicApi.list(2);
      if (interruptionsData) interruptions = interruptionsData;

      // 異常値検出ログ（tableIndex: 4）
      const anomaliesData = await window.aivicApi.list(4);
      if (anomaliesData) anomalies = anomaliesData;

      populateSelects();
      updatePreview();
    } catch (error) {
      console.error('初期データの読み込みに失敗しました:', error);
    }
  }

  // セレクトボックスの選択肢を設定
  function populateSelects() {
    // 作業員選択肢
    workerSelect.innerHTML = '<option value="all">全作業員</option>';
    users.filter(u => u.有効フラグ).forEach(user => {
      const option = document.createElement('option');
      option.value = user.ユーザーID;
      option.textContent = user.氏名;
      workerSelect.appendChild(option);
    });

    // 作業項目選択肢
    workItemSelect.innerHTML = '<option value="all">全作業項目</option>';
    workItems.filter(item => item.有効フラグ).forEach(item => {
      const option = document.createElement('option');
      option.value = item.作業項目ID;
      option.textContent = item.作業項目名;
      workItemSelect.appendChild(option);
    });

    // 作業場所選択肢
    const locations = [...new Set(workRecords.map(r => r.作業場所).filter(Boolean))];
    workLocationSelect.innerHTML = '<option value="">全場所</option>';
    locations.forEach(location => {
      const option = document.createElement('option');
      option.value = location;
      option.textContent = location;
      workLocationSelect.appendChild(option);
    });
  }

  // 抽出条件プレビューの更新
  function updatePreview() {
    const conditions = [];

    if (startDateInput.value) {
      conditions.push(`開始日: ${startDateInput.value}`);
    }
    if (endDateInput.value) {
      conditions.push(`終了日: ${endDateInput.value}`);
    }

    const selectedWorkers = Array.from(workerSelect.selectedOptions);
    if (selectedWorkers.length > 0 && !selectedWorkers.some(opt => opt.value === 'all')) {
      conditions.push(`作業員: ${selectedWorkers.map(opt => opt.textContent).join(', ')}`);
    }

    const selectedItems = Array.from(workItemSelect.selectedOptions);
    if (selectedItems.length > 0 && !selectedItems.some(opt => opt.value === 'all')) {
      conditions.push(`作業項目: ${selectedItems.map(opt => opt.textContent).join(', ')}`);
    }

    if (workLocationSelect.value) {
      conditions.push(`作業場所: ${workLocationSelect.value}`);
    }

    if (includeAnomalyCheckbox.checked) {
      conditions.push('異常値データを含む');
    }

    if (includeInterruptionCheckbox.checked) {
      conditions.push('中断記録を含む');
    }

    conditionPreview.textContent = conditions.length > 0 ? conditions.join(' / ') : '条件を設定してください';

    // データ件数の更新
    const filteredData = getFilteredData();
    dataCount.textContent = filteredData.length;
  }

  // フィルタリングされたデータの取得
  function getFilteredData() {
    let filtered = [...workRecords];

    // 期間フィルタ
    if (startDateInput.value) {
      const startDate = new Date(startDateInput.value);
      filtered = filtered.filter(record => new Date(record.作業日) >= startDate);
    }
    if (endDateInput.value) {
      const endDate = new Date(endDateInput.value);
      filtered = filtered.filter(record => new Date(record.作業日) <= endDate);
    }

    // 作業員フィルタ
    const selectedWorkers = Array.from(workerSelect.selectedOptions);
    if (selectedWorkers.length > 0 && !selectedWorkers.some(opt => opt.value === 'all')) {
      const workerIds = selectedWorkers.map(opt => opt.value);
      filtered = filtered.filter(record => workerIds.includes(record.作業員ID));
    }

    // 作業場所フィルタ
    if (workLocationSelect.value) {
      filtered = filtered.filter(record => record.作業場所 === workLocationSelect.value);
    }

    // 異常値除外
    if (!includeAnomalyCheckbox.checked) {
      const anomalyRecordIds = anomalies.map(a => a.検出対象レコードID);
      filtered = filtered.filter(record => !anomalyRecordIds.includes(record.作業記録ID));
    }

    // 中断記録除外
    if (!includeInterruptionCheckbox.checked) {
      filtered = filtered.filter(record => record.進捗状況 !== '中断');
    }

    return filtered;
  }

  // バリデーション
  function validateConditions() {
    hideError();

    if (!startDateInput.value || !endDateInput.value) {
      showError('抽出期間（開始日・終了日）を指定してください');
      return false;
    }

    if (new Date(startDateInput.value) > new Date(endDateInput.value)) {
      showError('開始日は終了日より前の日付を入力してください');
      return false;
    }

    const selectedWorkers = Array.from(workerSelect.selectedOptions);
    if (selectedWorkers.length === 0) {
      showError('作業員を選択してください');
      return false;
    }

    if (!outputFormatSelect.value) {
      showError('出力形式を選択してください');
      return false;
    }

    return true;
  }

  // エラー表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
  }

  // エラー非表示
  function hideError() {
    errorMessage.style.display = 'none';
  }

  // プレビュー表示
  function showPreview() {
    const filteredData = getFilteredData();
    const previewData = filteredData.slice(0, 100); // 最大100件

    if (previewData.length === 0) {
      previewTbody.innerHTML = '<tr><td colspan="7" style="text-align: center; padding: 20px; color: var(--text-muted);">該当するデータが見つかりませんでした</td></tr>';
    } else {
      previewTbody.innerHTML = previewData.map(record => {
        const worker = users.find(u => u.ユーザーID === record.作業員ID);
        const workTime = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}時間${record.作業時間 % 60}分` : '-';

        return `
          <tr>
            <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.作業日 || '-'}</td>
            <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${worker?.氏名 || '-'}</td>
            <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.プロジェクト名 || '-'}</td>
            <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.作業場所 || '-'}</td>
            <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.作業種別 || '-'}</td>
            <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${workTime}</td>
            <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.進捗状況 || '-'}</td>
          </tr>
        `;
      }).join('');
    }

    previewSection.style.display = 'block';
  }

  // データ抽出実行
  async function executeExtraction() {
    if (!validateConditions()) return;

    const filteredData = getFilteredData();

    if (filteredData.length === 0) {
      showError('抽出条件に該当するデータがありません');
      return;
    }

    // 最大件数チェック（10000件）
    if (filteredData.length > 10000) {
      showError('抽出データが最大件数（10,000件）を超えています。条件を絞り込んでください');
      return;
    }

    // 処理中表示
    showProcessing();

    try {
      // プログレスバー更新のシミュレーション
      updateProgress(30);
      await new Promise(resolve => setTimeout(resolve, 500));

      // データの整形
      const exportData = filteredData.map(record => {
        const worker = users.find(u => u.ユーザーID === record.作業員ID);
        return {
          作業日: record.作業日 || '',
          作業員: worker?.氏名 || '',
          プロジェクト名: record.プロジェクト名 || '',
          作業場所: record.作業場所 || '',
          作業種別: record.作業種別 || '',
          作業内容: record.作業内容 || '',
          作業開始時刻: record.作業開始時刻 || '',
          作業終了時刻: record.作業終了時刻 || '',
          作業時間: record.作業時間 || '',
          進捗状況: record.進捗状況 || '',
          承認状態: record.承認状態 || '',
          備考: record.備考 || ''
        };
      });

      updateProgress(70);
      await new Promise(resolve => setTimeout(resolve, 500));

      // ファイル出力
      if (outputFormatSelect.value === 'csv') {
        exportToCSV(exportData);
      } else if (outputFormatSelect.value === 'excel') {
        exportToExcel(exportData);
      }

      updateProgress(100);
      await new Promise(resolve => setTimeout(resolve, 300));

    } catch (error) {
      console.error('抽出処理でエラーが発生しました:', error);
      showError('データ抽出中にエラーが発生しました');
    } finally {
      hideProcessing();
    }
  }

  // CSV出力
  function exportToCSV(data) {
    if (data.length === 0) return;

    const headers = Object.keys(data[0]);
    const csvContent = [
      headers.join(','),
      ...data.map(row => 
        headers.map(header => {
          const value = row[header] || '';
          return value.toString().includes(',') ? `"${value}"` : value;
        }).join(',')
      )
    ].join('\n');

    const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `工数記録データ_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // Excel出力（CSV形式だが拡張子をxlsxに）
  function exportToExcel(data) {
    if (data.length === 0) return;

    const headers = Object.keys(data[0]);
    const csvContent = [
      headers.join(','),
      ...data.map(row => 
        headers.map(header => {
          const value = row[header] || '';
          return value.toString().includes(',') ? `"${value}"` : value;
        }).join(',')
      )
    ].join('\n');

    const blob = new Blob(['\uFEFF' + csvContent], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `工数記録データ_${new Date().toISOString().split('T')[0]}.xlsx`;
    link.click();
  }

  // 処理中表示
  function showProcessing() {
    processingOverlay.style.display = 'flex';
    updateProgress(0);
  }

  // 処理中非表示
  function hideProcessing() {
    processingOverlay.style.display = 'none';
  }

  // プログレスバー更新
  function updateProgress(percent) {
    progressBar.style.width = `${percent}%`;
  }

  // 条件保存
  function saveCondition() {
    const conditionName = prompt('条件名を入力してください:');
    if (!conditionName) return;

    const condition = {
      name: conditionName,
      startDate: startDateInput.value,
      endDate: endDateInput.value,
      workers: Array.from(workerSelect.selectedOptions).map(opt => opt.value),
      workItems: Array.from(workItemSelect.selectedOptions).map(opt => opt.value),
      workLocation: workLocationSelect.value,
      includeAnomaly: includeAnomalyCheckbox.checked,
      includeInterruption: includeInterruptionCheckbox.checked,
      outputFormat: outputFormatSelect.value
    };

    // ローカルストレージに保存
    const savedConditions = JSON.parse(localStorage.getItem('extractionConditions') || '[]');
    savedConditions.push(condition);
    localStorage.setItem('extractionConditions', JSON.stringify(savedConditions));

    alert('条件が保存されました');
  }

  // 条件クリア
  function clearConditions() {
    startDateInput.value = '';
    endDateInput.value = '';
    outputFormatSelect.value = '';
    workerSelect.selectedIndex = -1;
    workItemSelect.selectedIndex = -1;
    workLocationSelect.value = '';
    includeAnomalyCheckbox.checked = false;
    includeInterruptionCheckbox.checked = false;

    hideError();
    previewSection.style.display = 'none';
    updatePreview();
  }

  // イベントリスナーの設定
  startDateInput.addEventListener('change', updatePreview);
  endDateInput.addEventListener('change', updatePreview);
  workerSelect.addEventListener('change', updatePreview);
  workItemSelect.addEventListener('change', updatePreview);
  workLocationSelect.addEventListener('change', updatePreview);
  includeAnomalyCheckbox.addEventListener('change', updatePreview);
  includeInterruptionCheckbox.addEventListener('change', updatePreview);

  container.querySelector('#btn-preview').addEventListener('click', showPreview);
  container.querySelector('#btn-extract').addEventListener('click', executeExtraction);
  container.querySelector('#btn-save-condition').addEventListener('click', saveCondition);
  container.querySelector('#btn-clear-condition').addEventListener('click', clearConditions);
  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen("scr-1778907145716");
  });

  // 初期データ読み込み
  loadInitialData();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector('#records-tbody');
  const recordCount = container.querySelector('#record-count');
  const detailModal = container.querySelector('#detail-modal');
  const approveModal = container.querySelector('#approve-modal');
  let currentRecords = [];
  let currentApproveId = null;

  // 時間フォーマット関数
  function formatTime(timeStr) {
    if (!timeStr) return '';
    const date = new Date(timeStr);
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  // 日付フォーマット関数
  function formatDate(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP');
  }

  // 作業時間計算（分単位を時間:分に変換）
  function formatWorkTime(minutes) {
    if (!minutes) return '0時間0分';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}時間${mins}分`;
  }

  // 異常値チェック
  function checkAbnormalValues(record) {
    const warnings = [];

    // 24時間を超える作業時間
    if (record.作業時間 && record.作業時間 > 1440) {
      warnings.push('24時間を超える作業時間');
    }

    // 終了時刻が開始時刻より早い
    if (record.作業開始時刻 && record.作業終了時刻) {
      const start = new Date(record.作業開始時刻);
      const end = new Date(record.作業終了時刻);
      if (end < start) {
        warnings.push('終了時刻が開始時刻より早い');
      }
    }

    // 中断時間が実働時間を超える
    const breakTime = record.中断記録?.reduce((total, br) => total + (br.中断時間 || 0), 0) || 0;
    if (breakTime > (record.作業時間 || 0)) {
      warnings.push('中断時間が実働時間を超える');
    }

    return warnings;
  }

  // 承認状態のバッジ
  function getApprovalBadge(status) {
    const colors = {
      '未承認': 'background: rgba(255, 193, 7, 0.2); color: #856404; border: 1px solid rgba(255, 193, 7, 0.3);',
      '承認済み': 'background: rgba(40, 167, 69, 0.2); color: #155724; border: 1px solid rgba(40, 167, 69, 0.3);',
      '差し戻し': 'background: rgba(220, 53, 69, 0.2); color: #721c24; border: 1px solid rgba(220, 53, 69, 0.3);'
    };

    return `<span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; ${colors[status] || colors['未承認']}">${status || '未承認'}</span>`;
  }

  // テーブル再描画関数
  function renderRows(rows) {
    currentRecords = rows;
    recordCount.textContent = `${rows.length}件`;

    if (rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 13px;">作業項目がありません</td></tr>';
