          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatWorkTime(record.作業時間)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatWorkTime(breakTime)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${record.作業内容 || ''}</td>
