            <button class="action-btn approve-btn" data-id="${record.作業記録ID}" ${isApproved ? 'disabled' : ''} style="background: var(--primary); color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 11px; font-weight: 500; cursor: pointer; ${isApproved ? 'opacity: 0.5; cursor: not-allowed;' : ''}">承認</button>
