          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">作業者</label>
          <div style="font-size: 13px; color: var(--text);">${record.作業者名 || ''}</div>
        </div>
        <div>
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">開始時刻</label>
          <div style="font-size: 13px; color: var(--text);">${formatTime(record.作業開始時刻)}</div>
        </div>
        <div>
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">終了時刻</label>
          <div style="font-size: 13px; color: var(--text);">${formatTime(record.作業終了時刻)}</div>
        </div>
        <div>
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">実働時間</label>
          <div style="font-size: 13px; color: var(--text);">${formatWorkTime(record.作業時間)}</div>
        </div>
        <div>
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">中断時間</label>
          <div style="font-size: 13px; color: var(--text);">${formatWorkTime(breakTime)}</div>
        </div>
        <div>
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">プロジェクト名</label>
          <div style="font-size: 13px; color: var(--text);">${record.プロジェクト名 || ''}</div>
        </div>
        <div>
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">作業場所</label>
          <div style="font-size: 13px; color: var(--text);">${record.作業場所 || ''}</div>
        </div>
        <div>
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">作業種別</label>
          <div style="font-size: 13px; color: var(--text);">${record.作業種別 || ''}</div>
