      </div>
      <div>
        <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">作業内容</label>
        <div style="font-size: 13px; color: var(--text); padding: 8px; background: rgba(0,0,0,0.25); border-radius: 4px; min-height: 60px;">${record.作業内容 || ''}</div>
      </div>
      ${record.備考 ? `
      <div>
        <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">備考</label>
