    const headers = ['作業日', '作業者', '開始時刻', '終了時刻', '実働時間', '中断時間', '作業内容', '作業場所', '承認状態'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...currentRecords.map(record => {
        const breakTime = record.中断記録?.reduce((total, br) => total + (br.中断時間 || 0), 0) || 0;
        return [
          formatDate(record.作業日),
          record.作業者名 || '',
          formatTime(record.作業開始時刻),
          formatTime(record.作業終了時刻),
          formatWorkTime(record.作業時間),
          formatWorkTime(breakTime),
          `"${(record.作業内容 || '').replace(/"/g, '""')}"`,
          record.作業場所 || '',
          record.承認状態 || '未承認'
        ].join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `工数記録_${new Date().toISOString().split('T')[0]}.csv`;
