  });

  // 絞り込み検索
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const filterDate = container.querySelector('#filter-date').value;
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;

    // 日付範囲の妥当性チェック
    if (startDate && endDate && startDate > endDate) {
      alert('開始日は終了日より前の日付を指定してください');
      return;
    }

    const rows = await window.aivicApi.list(1);
    if (!rows) return;

    let filteredRows = rows;

    if (filterDate) {
      filteredRows = filteredRows.filter(record => {
        const recordDate = new Date(record.作業日).toISOString().split('T')[0];
        return recordDate === filterDate;
      });
    }

    if (startDate && endDate) {
      filteredRows = filteredRows.filter(record => {
        const recordDate = new Date(record.作業日).toISOString().split('T')[0];
        return recordDate >= startDate && recordDate <= endDate;
      });
    }

    renderRows(filteredRows);
  });

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // イベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 詳細表示
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      showDetail(detailBtn.dataset.id);
      return;
    }

    // 編集
    const editBtn = e.target.closest('.edit-btn');
    if (editBtn && !editBtn.disabled) {
      const record = currentRecords.find(r => r.作業記録ID === editBtn.dataset.id);
      if (record && record.承認状態 === '承認済み') {
        alert('承認済みの記録は修正できません');
        return;
      }
      window.showScreen('scr-1778907343735');
      return;
    }

    // 削除
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn && !deleteBtn.disabled) {
      const record = currentRecords.find(r => r.作業記録ID === deleteBtn.dataset.id);
      if (record && record.承認状態 === '承認済み') {
        alert('承認済みの記録は削除できません');
        return;
      }

      if (!confirm('この記録を削除しますか？')) return;

      await window.aivicApi.delete(1, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(1);
      if (rows) renderRows(rows);
      return;
    }

    // 承認
    const approveBtn = e.target.closest('.approve-btn');
    if (approveBtn && !approveBtn.disabled) {
      currentApproveId = approveBtn.dataset.id;
      approveModal.classList.remove('hidden');
      return;
    }

    // 詳細モーダルを閉じる
    if (e.target.id === 'close-detail' || e.target === detailModal) {
      detailModal.classList.add('hidden');
      return;
    }

    // 承認確認
    if (e.target.id === 'confirm-approve') {
      if (currentApproveId) {
        await window.aivicApi.update(1, currentApproveId, { 承認状態: '承認済み', 承認日時: new Date().toISOString() });
        const rows = await window.aivicApi.list(1);
        if (rows) renderRows(rows);
      }
      approveModal.classList.add('hidden');
      currentApproveId = null;
      return;
    }

    // 承認キャンセル
    if (e.target.id === 'cancel-approve' || e.target === approveModal) {
      approveModal.classList.add('hidden');
      currentApproveId = null;
      return;
    }
  });

  // 今日の日付をデフォルトで設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#filter-date').value = today;
}

function(container, apiUrl, tables) {
  // 現在のユーザー情報（実際の実装では認証から取得）
  const currentUser = { id: 'user-001', name: '田中太郎' };

  // 作業項目マスタの読み込み
  async function loadWorkItems() {
    const workItems = await window.aivicApi.list(3); // 作業項目マスタ
    const workItemSelect = container.querySelector('#work-item');
    workItemSelect.innerHTML = '<option value="">選択してください</option>';
    if (workItems) {
      workItems.forEach(item => {
        const option = document.createElement('option');
        option.value = item.作業項目ID;
        option.textContent = item.作業項目名;
        workItemSelect.appendChild(option);
      });
    }
  }

  // 工数計算
  function calculateHours() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;

    if (!startTime || !endTime) {
      container.querySelector('#total-hours').textContent = '0:00';
      container.querySelector('#break-hours').textContent = '0:00';
      container.querySelector('#net-hours').textContent = '0:00';
      return { totalMinutes: 0, breakMinutes: 0, netMinutes: 0 };
    }

    const start = new Date(`2000-01-01T${startTime}`);
    const end = new Date(`2000-01-01T${endTime}`);

    // 終了時刻が開始時刻より前の場合は翌日とみなす
    if (end < start) {
      end.setDate(end.getDate() + 1);
    }

    const totalMinutes = (end - start) / (1000 * 60);
    const breakMinutes = breakTime;
    const netMinutes = Math.max(0, totalMinutes - breakMinutes);

    container.querySelector('#total-hours').textContent = formatMinutes(totalMinutes);
    container.querySelector('#break-hours').textContent = formatMinutes(breakMinutes);
    container.querySelector('#net-hours').textContent = formatMinutes(netMinutes);

    return { totalMinutes, breakMinutes, netMinutes };
  }

  function formatMinutes(minutes) {
    const hours = Math.floor(minutes / 60);
    const mins = Math.floor(minutes % 60);
    return `${hours}:${mins.toString().padStart(2, '0')}`;
  }

  // バリデーション
  function validateForm() {
    const errors = [];
    const workDate = container.querySelector('#work-date').value;
    const projectName = container.querySelector('#project-name').value;
    const workItem = container.querySelector('#work-item').value;
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const workLocation = container.querySelector('#work-location').value;
    const workContent = container.querySelector('#work-content').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;

    // 必須項目チェック
    if (!workDate) errors.push('作業日付は必須です');
    if (!projectName) errors.push('プロジェクト名は必須です');
    if (!workItem) errors.push('作業項目は必須です');
    if (!startTime) errors.push('作業開始時刻は必須です');
    if (!endTime) errors.push('作業終了時刻は必須です');
    if (!workLocation) errors.push('作業場所は必須です');
    if (!workContent.trim()) errors.push('作業内容詳細は必須です');

    // 未来日付チェック
    if (workDate) {
      const today = new Date().toISOString().split('T')[0];
      if (workDate > today) {
        errors.push('未来日付は選択できません');
      }
    }

    // 時刻チェック
    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);

      // 同日で終了時刻が開始時刻より前の場合はエラー
      if (end <= start && !(endTime === '00:00' || endTime < startTime)) {
        errors.push('開始時刻が終了時刻より後になっています');
      }

      // 24時間以上の作業時間チェック
      let totalMinutes = (end - start) / (1000 * 60);
      if (end < start) {
        totalMinutes = (24 * 60) - ((start - end) / (1000 * 60));
      }

      if (totalMinutes >= 24 * 60) {
        errors.push('24時間以上の作業時間は入力できません');
      }

      // 中断時間が作業時間を超過するかチェック
      if (breakTime > 0 && breakTime >= totalMinutes) {
        errors.push('中断時間は作業時間を超過できません');
      }
    }

    // 文字数制限チェック
    if (workContent.length > 1000) {
      errors.push('作業内容詳細は1000文字以内で入力してください');
    }

    return errors;
  }

  function showErrors(errors) {
    const errorDiv = container.querySelector('#error-messages');
    const errorList = container.querySelector('#error-list');

    if (errors.length > 0) {
      errorList.innerHTML = errors.map(error => `<li>${error}</li>`).join('');
      errorDiv.style.display = 'block';
    } else {
      errorDiv.style.display = 'none';
    }
  }

  function showSuccess(message) {
    const successDiv = container.querySelector('#success-message');
    successDiv.textContent = message;
    successDiv.style.display = 'block';
    setTimeout(() => {
      successDiv.style.display = 'none';
    }, 3000);
  }

  function clearForm() {
    container.querySelector('#work-record-form').reset();
    container.querySelector('#work-content').value = '';
    container.querySelector('#char-count').textContent = '0';
    calculateHours();
    showErrors([]);
  }

  async function saveRecord(isTemp = false) {
    const errors = validateForm();
    if (errors.length > 0) {
      showErrors(errors);
      return;
    }

    const { totalMinutes, netMinutes } = calculateHours();
    const workDate = container.querySelector('#work-date').value;
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;

    const recordData = {
      作業員ID: currentUser.id,
      作業日: new Date(`${workDate}T${startTime}`).toISOString(),
      作業開始時刻: new Date(`${workDate}T${startTime}`).toISOString(),
      作業終了時刻: new Date(`${workDate}T${endTime}`).toISOString(),
      作業時間: Math.floor(netMinutes),
      プロジェクト名: container.querySelector('#project-name').value,
      作業場所: container.querySelector('#work-location').value,
      作業種別: container.querySelector('#work-item option:checked').textContent,
      作業内容: container.querySelector('#work-content').value,
      進捗状況: isTemp ? '一時保存' : '完了',
      備考: '',
      承認状態: '未承認',
      作成者ID: currentUser.id
    };

    const saved = await window.aivicApi.save(1, recordData); // 作業記録テーブル
    if (saved) {
      showSuccess(isTemp ? '一時保存しました' : '工数記録を登録しました');
      if (!isTemp) {
        clearForm();
        // 作業履歴一覧画面に遷移
        setTimeout(() => {
          window.showScreen('scr-1778907145716');
        }, 1500);
      }
    }
  }

  // 初期設定
  loadWorkItems();

  // 今日の日付を初期値に設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#work-date').value = today;

  // 文字数カウント
  container.querySelector('#work-content').addEventListener('input', (e) => {
    container.querySelector('#char-count').textContent = e.target.value.length;
  });

  // 時刻変更時の自動計算
  container.querySelector('#start-time').addEventListener('change', calculateHours);
  container.querySelector('#end-time').addEventListener('change', calculateHours);
  container.querySelector('#break-time').addEventListener('input', calculateHours);

  // 工数計算ボタン
  container.querySelector('#btn-calc-hours').addEventListener('click', calculateHours);

  // 一時保存ボタン
  container.querySelector('#btn-temp-save').addEventListener('click', () => {
    saveRecord(true);
  });

  // 記録確定ボタン
  container.querySelector('#btn-save').addEventListener('click', () => {
    if (confirm('工数記録を確定しますか？')) {
      saveRecord(false);
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    if (confirm('入力内容をクリアしますか？')) {
      clearForm();
    }
  });

  // 中断記録モーダル
  const breakModal = container.querySelector('#break-modal');

  container.querySelector('#btn-add-break').addEventListener('click', () => {
    breakModal.classList.remove('hidden');
  });

  container.querySelector('#btn-cancel-break').addEventListener('click', () => {
    breakModal.classList.add('hidden');
  });

  container.querySelector('#btn-add-break-record').addEventListener('click', async () => {
    const reason = container.querySelector('#break-reason').value;
    const duration = parseInt(container.querySelector('#break-duration').value);

    if (!duration || duration <= 0) {
      alert('中断時間を正しく入力してください');
      return;
    }

    // 現在の中断時間に追加
    const currentBreakTime = parseInt(container.querySelector('#break-time').value) || 0;
    container.querySelector('#break-time').value = currentBreakTime + duration;

    calculateHours();
    breakModal.classList.add('hidden');

    // 中断記録をリセット
    container.querySelector('#break-duration').value = '';
  });

  // モーダル外クリックで閉じる
  breakModal.addEventListener('click', (e) => {
    if (e.target === breakModal) {
      breakModal.classList.add('hidden');
    }
  });
}
